/* ---------- Confirmar una compra (reutilizado por el panel y por el webhook de MP) ---------- */
async function confirmarCompra(env, tenantId, tenant, compra){
  /* La ficha nueva se crea con apellido/email/nacimiento, que son columnas agregadas por
     migracion: hay que garantizarlas antes del INSERT o el pago confirmado se cae. */
  await ensureAlumnoExtraSchema(env).catch(() => {});
  if (!compra) return { ok: false, error: "Compra no encontrada", status: 404 };
  /* 'cancelada' tambien se acredita: es un intento de tarjeta reemplazado por un reintento,
     pero su preference de MP sigue pagable. Si el pago aprobado llega por ella, es plata real. */
  if (compra.estado !== "pendiente" && compra.estado !== "iniciada" && compra.estado !== "cancelada"){
    return { ok: false, error: "Esa compra ya fue procesada", status: 409 };
  }
  const cu = await env.DB.prepare("SELECT * FROM cuentas WHERE id = ?1 AND tenant_id = ?2").bind(compra.cuenta_id, tenantId).first();
  if (!cu) return { ok: false, error: "La cuenta de esa compra ya no existe", status: 404 };

  if (compra.paquete === "Clase de prueba" && cu.alumno_id){
    return { ok: false, error: "La clase de prueba es solo para la primera clase de una cuenta nueva.", status: 400 };
  }

  const reclamo = await env.DB.prepare(
    "UPDATE compras SET estado = 'confirmada' WHERE id = ?1 AND tenant_id = ?2 AND estado IN ('pendiente','iniciada','cancelada')"
  ).bind(compra.id, tenantId).run();
  const filasReclamo = (reclamo && reclamo.meta && (reclamo.meta.changes ?? reclamo.meta.rows_written)) || 0;
  if (!filasReclamo){
    return { ok: false, error: "Esa compra ya fue procesada", status: 409, yaProcesada: true };
  }

  const stmts = [];
  let renovado = false;
  let alumnoIdNuevo = null;
  /* Config y planes del tenant: se cargan UNA vez y se pasan a todo lo de abajo (referidos,
     arrastre del bonus, cursos del alumno nuevo). Antes cada bloque los volvia a pedir. */
  const cfgConfirm = await loadConfig(env, tenantId).catch(() => ({}));
  const paqMapConfirm = await loadPaquetes(env, tenantId).then(p => p.map).catch(() => ({}));
  const vence = new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10);
  if (cu.alumno_id){
    const al = await env.DB.prepare("SELECT * FROM alumnos WHERE id = ?1 AND tenant_id = ?2").bind(cu.alumno_id, tenantId).first();
    /* ═══ V2 (11-ago-2026): COMPRAR UN PASE MÁS, sin pisar los que ya tiene ═══
       Regla, que es como lo entiende cualquiera: si al alumno TODAVÍA le queda algo vivo,
       lo que compra se SUMA como pase nuevo (el de Barré no se come al de Máquinas ni le
       resetea el ciclo). Si ya no le queda nada, es la renovación clásica de siempre.
       Ojo con el ciclo: los pases viven atados a él, así que sumar NO puede subirlo. */
    let sumado = false;
    if (al){
      try {
        const paqMapC = (await loadPaquetes(env, tenantId)).map;
        const pkComprado = resolverPk(paqMapC, compra.paquete);
        const yaTiene = pasesDe(al);
        const cicloAct = Number(al.ciclo) || 1;
        let vivoAntes = false;
        if (yaTiene){
          const cmC = await computeMulti(env, tenantId, al, paqMapC, {});
          vivoAntes = cmC.pases.some(p => !p.vencido && (p.ilim || p.restantes > 0));
        } else if (al.paquete){
          const pkAct = resolverPk(paqMapC, al.paquete);
          const cicloA = Number(al.ciclo) || 1;
          const { results: regsA } = await env.DB.prepare(
            SQL_REGS_CICLO
          ).bind(tenantId, al.id, cicloA).all();
          const rUsA = await reservasUsadasCount(env, tenantId, al.id, cicloA);
          const cA = compute(al, regsA || [], {}, rUsA, pkAct);
          vivoAntes = !Number(al.caducado) && !venceVencido(al.vence) && (cA.ilim || cA.restantes > 0);
        }
        /* la clase de prueba nunca suma pase: es puerta de entrada, no un plan paralelo */
        if (vivoAntes && compra.paquete !== "Clase de prueba"){
          const lista = yaTiene ? yaTiene.slice() : [{
            n: al.paquete,
            usadas: ((Number(al.migrado_ciclo) || 0) === cicloAct) ? (Number(al.migrado_usadas) || 0) : 0,
            vence: al.vence || ""
          }];
          const vencePase = pkComprado.dias
            ? calcularVence(pkComprado, { fecha: hoyLima(), activado: "" }, "")
            : (pkComprado.ilim ? vence : "");
          lista.push({ n: compra.paquete, usadas: 0, vence: vencePase });
          const pj = sanearPasesJson({ c: cicloAct, p: lista }, cicloAct);
          if (pj){
            stmts.push(env.DB.prepare(
              "UPDATE alumnos SET pases = ?1, pago = 'Pagado' WHERE id = ?2 AND tenant_id = ?3"
            ).bind(pj, al.id, tenantId));
            /* las reservas futuras NO se migran de ciclo: el ciclo no cambió, siguen válidas */
            sumado = true;
            renovado = true;   // ya se atendió a este alumno: no crear ficha nueva
          }
        }
      } catch (e) { /* cualquier problema: cae a la renovación clásica de abajo */ }
    }
    if (al && !sumado){
      const cicloNuevo = (Number(al.ciclo) || 1) + 1;
      /* caducado = 0 + activado = '': renovar REVIVE al alumno caducado (promesa del cron
         caducarPlanesSinArrancar) y el ciclo nuevo arranca su vigencia de cero — el mismo
         reset que hace el guardado manual de la ficha. Sin esto, el alumno pagaba su
         renovacion y reservar lo seguia rebotando con 'Tu plan caduco'. */
      stmts.push(env.DB.prepare(
        "UPDATE alumnos SET paquete = ?1, curso = ?2, pago = 'Pagado', fecha = ?3, ciclo = ?4, vence = ?5, aviso_vence_ciclo = 0, caducado = 0, activado = '' WHERE id = ?6 AND tenant_id = ?7"
      ).bind(compra.paquete, compra.curso || al.curso, hoyLima(), cicloNuevo, vence, al.id, tenantId));
      /* Migrar las reservas FUTURAS al ciclo nuevo: si no, el credito de esas clases queda
         huerfano en el ciclo viejo y la clase se carga mal al paquete nuevo (bug MVT 21-jul).

         🐛 14-ago-2026 (José/Elevate, caso Daniela Guerra-García): se migraban TODAS, y eso
         cobra dos veces las que el paquete ANTERIOR ya había pagado. Ella entró con 6 de 8
         usadas del sistema viejo, reservó las 2 que le quedaban (ciclo viejo: 8 de 8, cerrado),
         compró otro paquete de 8 y esas 2 reservas se mudaron y le dejaron 6 en vez de 8.
         Pagó 16 clases y podía tomar 14.

         Ahora se migran SOLO las que el paquete viejo NO alcanzaba a cubrir. Las que ya estaban
         pagadas se quedan en su ciclo, que es donde se pagaron. El motivo original se respeta
         igual: ninguna reserva queda sin paquete que la sostenga. */
      let migrarIds = null;
      try {
        const paqMapR = (await loadPaquetes(env, tenantId)).map;
        const pkAnt = resolverPk(paqMapR, al.paquete);
        const cicloAnt = Number(al.ciclo) || 1;
        const { results: regsAnt } = await env.DB.prepare(
          SQL_REGS_CICLO
        ).bind(tenantId, al.id, cicloAnt).all();
        /* reservasUsadas = 0 a propósito: acá quiero SOLO lo que consumió la bitácora, para
           saber cuánto del paquete viejo quedaba libre para sostener reservas futuras. */
        /* 🔴 22-ago-2026: con compute() pelado, un alumno de VARIOS pases contaba solo la
           capacidad de `al.paquete`. `cubiertas` salía corto y se le mudaban al ciclo nuevo
           reservas futuras que sus pases viejos YA habían pagado: volvía a pagarlas. */
        const cAnt = pasesDe(al)
          ? await computeMulti(env, tenantId, al, paqMapR, {}, "", { resv: [], regs: regsAnt || [] })
          : compute(al, regsAnt || [], {}, 0, pkAnt);
        const cubiertas = cAnt.ilim ? 1e9 : Math.max(0, (Number(cAnt.compradas) || 0) - (Number(cAnt.usadas) || 0));
        const { results: futuras } = await env.DB.prepare(
          "SELECT id FROM reservas WHERE tenant_id = ?1 AND alumno_id = ?2 AND estado = 'reservada' AND inicio_utc >= ?3 ORDER BY inicio_utc ASC"
        ).bind(tenantId, al.id, new Date().toISOString()).all();
        /* las primeras `cubiertas` (las más próximas) ya están pagadas por el paquete viejo */
        migrarIds = (futuras || []).slice(cubiertas).map(r => r.id);
      } catch (e) { migrarIds = null; }   // si algo falla, se cae al comportamiento de siempre
      if (migrarIds){
        for (const rid of migrarIds){
          stmts.push(env.DB.prepare("UPDATE reservas SET ciclo = ?1 WHERE id = ?2 AND tenant_id = ?3").bind(cicloNuevo, rid, tenantId));
        }
      } else {
        stmts.push(env.DB.prepare(
          "UPDATE reservas SET ciclo = ?1 WHERE tenant_id = ?2 AND alumno_id = ?3 AND estado = 'reservada' AND inicio_utc >= ?4"
        ).bind(cicloNuevo, tenantId, al.id, new Date().toISOString()));
      }
      /* ── El regalo por referir no se pierde al renovar (15-ago-2026) ──
         `bonus_clases` va atado al ciclo, asi que al subir el ciclo se apagaria solo y el
         alumno perderia una clase que se gano. Lo que le quedaba SIN USAR se muda al ciclo
         nuevo; lo que ya consumio, no. Se calcula sobre el ciclo viejo: el bonus recien se
         empieza a gastar cuando las usadas pasan las clases que compro.
         Si algo falla acá, el bonus queda apuntando al ciclo viejo = inerte. Se pierde el
         regalo, que es feo, pero nunca se regala una clase por cada renovacion. */
      try {
        const bonusAnt = ((Number(al.bonus_ciclo) || 0) === (Number(al.ciclo) || 1))
          ? Math.max(0, Number(al.bonus_clases) || 0) : 0;
        if (bonusAnt > 0){
          const pkAntB = resolverPk(paqMapConfirm, al.paquete);
          const { results: regsAntB } = await env.DB.prepare(
            SQL_REGS_CICLO
          ).bind(tenantId, al.id, Number(al.ciclo) || 1).all();
          /* 🔴 22-ago-2026: igual que arriba. Con varios pases, el umbral de "clases que de
             verdad pagó" era solo el de `al.paquete`, así que el bonus se daba por consumido
             antes de tiempo y el alumno perdía clases de regalo al renovar. */
          const multiB = pasesDe(al);
          const cAntB = multiB
            ? await computeMulti(env, tenantId, al, paqMapConfirm, {}, "", { resv: [], regs: regsAntB || [] })
            : compute(al, regsAntB || [], {}, 0, pkAntB);
          /* `compradas` ya viene con el bonus sumado, en las dos rutas: lo pagado de verdad es
             `compradas - bonus`, y el consumido es lo que se comió POR ENCIMA de eso. */
          const pagadas = multiB
            ? Math.max(0, (Number(cAntB.compradas) || 0) - (Number(cAntB.bonus) || 0))
            : (Number(pkAntB.clases) || 0);
          const consumido = (multiB ? false : pkAntB.ilim) ? bonusAnt
            : Math.min(bonusAnt, Math.max(0, (Number(cAntB.usadas) || 0) - pagadas));
          const restante = Math.max(0, bonusAnt - consumido);
          stmts.push(env.DB.prepare("UPDATE alumnos SET bonus_clases = ?1, bonus_ciclo = ?2 WHERE id = ?3 AND tenant_id = ?4")
            .bind(restante, restante > 0 ? cicloNuevo : 0, al.id, tenantId));
        }
      } catch (e) { console.error("referido: no se pudo arrastrar el bonus al renovar", e); }
      renovado = true;
    }
  }
  if (!renovado){
    const nuevoId = crypto.randomUUID();
    alumnoIdNuevo = nuevoId;
    const cursoNuevo = compra.curso || cursosDeCfg(await loadConfig(env, tenantId))[0];
    /* multi-profesor: el alumno nuevo nace asignado al profe atribuido en la compra, o al dueno */
    let profeNuevo = compra.profesor_id || null;
    if (!profeNuevo){
      const dN = await duenoDeTenant(env, tenantId).catch(() => null);
      profeNuevo = dN ? dN.id : null;
    }
    /* apellido/nacimiento los recogio el formulario publico y quedaron en la cuenta: aqui
       se copian a la ficha, que es donde el profe los ve. Si la academia no los pidio, van
       vacios y la ficha queda igual que siempre. */
    stmts.push(env.DB.prepare(
      "INSERT INTO alumnos (id,tenant_id,codigo,nombre,whatsapp,curso,paquete,fecha,pago,horario,notas,ciclo,vence,profesor_id,apellido,email,nacimiento) VALUES (?1,?2,?3,?4,?5,?6,?7,?8,'Pagado','','Creado por compra web',1,?9,?10,?11,?12,?13)"
    ).bind(nuevoId, tenantId, randHex(3).toUpperCase(), cu.nombre, cu.whatsapp || "", cursoNuevo, compra.paquete, hoyLima(), vence, profeNuevo,
           cu.apellido || "", cu.email || "", cu.nacimiento || ""));
    stmts.push(env.DB.prepare("UPDATE cuentas SET alumno_id = ?1 WHERE id = ?2 AND tenant_id = ?3").bind(nuevoId, cu.id, tenantId));
  }
  /* atribucion del ingreso al profesor del alumno (reporte "ingresos por profe" del dueno) */
  try {
    let profAtrib = compra.profesor_id || null;
    if (!profAtrib && cu.alumno_id){
      const alA = await env.DB.prepare("SELECT profesor_id FROM alumnos WHERE id = ?1 AND tenant_id = ?2").bind(cu.alumno_id, tenantId).first();
      profAtrib = (alA && alA.profesor_id) || null;
    }
    if (profAtrib){
      stmts.push(env.DB.prepare("UPDATE compras SET profesor_id = ?1 WHERE id = ?2 AND tenant_id = ?3").bind(profAtrib, compra.id, tenantId));
    }
  } catch (e) {}

  /* OJO: el claim de arriba YA puso ESTA compra en 'confirmada', asi que los COUNT deben
     excluirla (AND id != compra.id). Sin eso, esPrimera/esPrimeraReal daban SIEMPRE false:
     el credito de referido S/50 no se pagaba nunca y el correo de bienvenida nunca salia. */
  const previas = await env.DB.prepare(
    "SELECT COUNT(*) AS n FROM compras WHERE tenant_id = ?1 AND cuenta_id = ?2 AND estado = 'confirmada' AND id != ?3"
  ).bind(tenantId, cu.id, compra.id).first();
  const esPrimera = !previas || !Number(previas.n);

  /* ═══ EL PREMIO DEL QUE REFIRIO (reescrito el 15-ago-2026 con las reglas de José/Elevate) ═══
     Antes: S/50 de credito, siempre, para toda academia. Ahora: lo que la academia haya armado
     en Ajustes > Referidos, y solo si la compra pasa TODAS sus condiciones (primera compra, plan
     que no sea promocion, minimo de clases, y el amigo sin historial previo si asi lo pidio).
     Las condiciones son las MISMAS que le dieron el descuento al amigo al comprar: si una de
     las dos puntas fallara sola, uno cobraria y el otro no. */
  if (cu.ref_por){
    const rcC = refCfg(cfgConfirm);
    const pkC = resolverPk(paqMapConfirm, compra.paquete);
    const elC = await refElegible(env, tenantId, cu, compra.paquete, pkC, rcC, compra.id);
    const refidor = elC.ok
      ? await env.DB.prepare("SELECT id, alumno_id FROM cuentas WHERE tenant_id = ?1 AND ref_code = ?2").bind(tenantId, cu.ref_por).first()
      : null;
    /* auto-referido NO: quien se registra con su propio codigo se estaria pagando solo */
    if (refidor && refidor.id !== cu.id){
      let creditoPremio = 0;
      let clasesPremio = 0;
      if (rcC.premioModo === "soles"){
        creditoPremio = rcC.premioValor;
      } else if (rcC.premioModo === "pct_compra"){
        /* sobre lo que el amigo PAGO de verdad, no sobre el precio de lista: si uso su credito
           o su descuento de bienvenida, la academia no vio esa plata y no puede repartirla */
        creditoPremio = Math.round(Math.max(0, Number(compra.monto) || 0) * rcC.premioValor) / 100;
      } else {
        /* "N clases gratis". En modo `clases_saldo` van al saldo del que refirio y las puede
           reservar sin comprar nada; en `clases_credito` se pagan como credito, al precio de
           una clase del plan que acaba de comprar el amigo.
           Un plan de mensualidad ilimitada no tiene precio por clase: ahi el modo credito no
           sabe cuanto vale el premio y no inventa un numero (se cae a 0 y queda en el log). */
        const nClases = Math.max(1, Math.floor(rcC.premioValor));
        if (rcC.premioModo === "clases_saldo" && refidor.alumno_id){
          clasesPremio = nClases;
        } else {
          const preciosC = await loadPrecios(env, tenantId).catch(() => ({}));
          const unit = precioPorClase((preciosC && preciosC[compra.paquete]) || 0, pkC);
          creditoPremio = Math.round(unit * nClases * 100) / 100;
          if (!creditoPremio) console.log("referido: premio en clases sin precio por clase", tenantId, compra.paquete);
        }
      }
      if (creditoPremio > 0){
        stmts.push(env.DB.prepare("UPDATE cuentas SET credito = COALESCE(credito,0) + ?1 WHERE id = ?2 AND tenant_id = ?3")
          .bind(creditoPremio, refidor.id, tenantId));
      }
      if (clasesPremio > 0){
        /* El bonus vive atado al ciclo VIGENTE del que refirio (mismo patron que migrado_usadas).
           Si ya tenia bonus de este ciclo se acumula; si el que tenia era de un ciclo viejo ya
           estaba inerte y se pisa. Se lee la ficha aca y no en el batch porque hay que saber en
           que ciclo esta parado para no regalarle una clase que nunca va a poder usar. */
        try {
          const alR = await env.DB.prepare("SELECT ciclo, COALESCE(bonus_clases,0) AS bc, COALESCE(bonus_ciclo,0) AS bcl FROM alumnos WHERE id = ?1 AND tenant_id = ?2")
            .bind(refidor.alumno_id, tenantId).first();
          if (alR){
            const cicloR = Number(alR.ciclo) || 1;
            const acum = (Number(alR.bcl) === cicloR ? Math.max(0, Number(alR.bc) || 0) : 0) + clasesPremio;
            stmts.push(env.DB.prepare("UPDATE alumnos SET bonus_clases = ?1, bonus_ciclo = ?2 WHERE id = ?3 AND tenant_id = ?4")
              .bind(acum, cicloR, refidor.alumno_id, tenantId));
          }
        } catch (e) { console.error("referido: no se pudo abonar la clase de regalo", e); }
      }
    }
  }

  const usado = Number(compra.descuento) || 0;
  if (usado > 0){
    stmts.push(env.DB.prepare(
      "UPDATE cuentas SET credito = CASE WHEN COALESCE(credito,0) - ?1 < 0 THEN 0 ELSE COALESCE(credito,0) - ?1 END WHERE id = ?2 AND tenant_id = ?3"
    ).bind(usado, cu.id, tenantId));
  }

  try {
    await env.DB.batch(stmts);
  } catch (e) {
    console.error(e);
    try {
      await env.DB.prepare("UPDATE compras SET estado = ?1 WHERE id = ?2 AND tenant_id = ?3 AND estado = 'confirmada'")
        .bind(compra.estado, compra.id, tenantId).run();
    } catch (e2) { console.error(e2); }
    return { ok: false, error: "No se pudo aplicar la compra. Intenta de nuevo.", status: 500 };
  }

  if (!renovado && alumnoIdNuevo && compra.paquete === "Clase de prueba" && compra.slot_deseado) {
    try {
      if (await slotValido(env, tenantId, compra.slot_deseado)) {
        const finIso = new Date(Date.parse(compra.slot_deseado) + CLASE_MIN * 60000).toISOString();
        const rid = crypto.randomUUID();
        await env.DB.prepare(
          "INSERT INTO reservas (id,tenant_id,alumno_id,inicio_utc,fin_utc,tipo,serie_id,estado,curso,ciclo,creada) VALUES (?1,?2,?3,?4,?5,'suelta','','reservada',?6,1,?7)"
        ).bind(rid, tenantId, alumnoIdNuevo, compra.slot_deseado, finIso, compra.curso || "Canto", new Date().toISOString()).run();
      }
    } catch (e) { /* alguien tomo ese horario mientras tanto; el alumno lo reserva desde el portal */ }
  }

  if (esPrimera) { try { await correoBienvenidaAlumno(env, tenant, cu, compra); } catch (e) {} }
  try {
    await avisarPushAlumno(env, tenantId, cu.id, {
      title: "Pago confirmado",
      body: "Tu paquete " + (compra.paquete || "") + " ya esta activo. Reserva tu proxima clase.",
      url: MARCA.dominio + "/app/a/" + (tenant ? tenant.slug : "")
    });
  } catch (e) {}
  return { ok: true, cu, compra };
}

/* ============ CHATBOT / ONBOARDING IA: apagados en v0 (guard por falta de binding/secreto) ============ */
async function responderChatbot(env, tenant, mensajes){
  const wa = "https://wa.me/" + ((tenant && tenant.whatsapp) || MARCA.whatsapp);
  const fallback = "Para eso lo mejor es que hables directo con tu profesor. Escribele por WhatsApp: " + wa;
  if (!env.AI) return fallback;
  try {
    const resp = await env.AI.run("@cf/meta/llama-3.3-70b-instruct-fp8-fast", {
      messages: [{ role: "system", content: "Eres el asistente virtual de " + (tenant ? tenant.academia : MARCA.nombre) + ". Responde corto, en espanol, sin prometer resultados garantizados. No uses signos de apertura invertidos (nada de ¿ ni ¡); usa solo los de cierre. Si no sabes algo, ofrece el WhatsApp: " + wa }].concat(mensajes),
      max_tokens: 400
    });
    const texto = sanearRespuestaIA((resp && (resp.response || "")).trim());
    return texto || fallback;
  } catch (e) { return fallback; }
}

/* IP REAL del cliente. El tráfico llega por el proxy de Vercel, así que CF-Connecting-IP
   es la IP de egress compartida de Vercel (el rate-limit por esa clave sería global e inútil).
   La IP real del visitante viaja en x-forwarded-for (primer valor) / x-real-ip. (07-jul-2026) */
function clientIp(request){
  const xff = request.headers.get("x-forwarded-for") || "";
  if (xff){ const first = xff.split(",")[0].trim(); if (first) return first; }
  return request.headers.get("x-real-ip") || request.headers.get("cf-connecting-ip") || "";
}

async function chatbotPasoTope(env, ip, limite){
  if (!ip) return false;
  const ventana = new Date().toISOString().slice(0, 13);
  const LIMITE = limite || 40;
  try {
    await env.DB.prepare(
      "INSERT INTO chatbot_uso (ip, ventana, n) VALUES (?1, ?2, 1) ON CONFLICT(ip, ventana) DO UPDATE SET n = n + 1"
    ).bind(ip, ventana).run();
    const row = await env.DB.prepare("SELECT n FROM chatbot_uso WHERE ip = ?1 AND ventana = ?2").bind(ip, ventana).first();
    return !!(row && Number(row.n) > LIMITE);
  } catch (e) { return false; }
}

/* Onboarding IA: Claude (Anthropic) si hay key; si no, cae al binding AI de Cloudflare
   (Workers AI, Llama, gratis dentro del free tier). Así el asistente vive aunque no haya
   ANTHROPIC_API_KEY. Devuelve null solo si ninguna vía responde (el handler degrada con gracia). */
// Sanea la salida de la IA al estilo de marca: sin signos de apertura invertidos
// (¿ ¡). Llama a veces malinterpreta "signos solo al cierre" y pega un "¿?" al
// final; esto lo elimina y limpia espacios sueltos antes de la puntuacion.
function sanearRespuestaIA(t){
  if (!t) return t;
  return String(t)
    .replace(/¿\s*\?/g, "")        // "¿?" espurio -> nada
    .replace(/¡\s*!/g, "")          // "¡!" espurio -> nada
    .replace(/[¿¡]/g, "")           // sin signos de apertura (estilo de marca)
    .replace(/\s+([?!.,;:])/g, "$1") // espacio antes de puntuacion -> pegado
    .replace(/\s{2,}/g, " ")
    .trim();
}
async function llamarClaudeOnboarding(env, system, mensajes, extraSystem, modelo){
  const extra = String(extraSystem || "").trim();
  /* modelo opcional (10-ago-2026): la rama negocio puede pedir Sonnet para la linea PROPIA de
     venta de Batuta (kb.modelo = "sonnet"); todo lo demas sigue en Haiku (el modelo de clientes). */
  const modeloId = modelo === "sonnet" ? "claude-sonnet-4-5-20250929" : "claude-haiku-4-5-20251001";
  if (env.ANTHROPIC_API_KEY){
    try {
      /* system en 2 bloques: el manual largo y FIJO lleva cache_control (en conversaciones
         seguidas se lee del cache de Anthropic, ~10x mas barato) y el contexto de SESION
         (rol del actor, modulos ocultos) va en un bloque chico aparte SIN cache, para no
         fragmentar el cache del manual por cada combinacion. */
      const sysBlocks = [{ type: "text", text: system, cache_control: { type: "ephemeral" } }];
      if (extra) sysBlocks.push({ type: "text", text: extra });
      const resp = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: {
          "x-api-key": env.ANTHROPIC_API_KEY,
          "anthropic-version": "2023-06-01",
          "content-type": "application/json"
        },
        body: JSON.stringify({ model: modeloId, max_tokens: 350, system: sysBlocks, messages: mensajes })
      });
      if (resp.ok){
        const data = await resp.json().catch(() => null);
        const bloque = data && Array.isArray(data.content) ? data.content.find(c => c.type === "text") : null;
        const t = bloque ? String(bloque.text || "").trim() : "";
        if (t) return sanearRespuestaIA(t);
      }
    } catch (e) { /* cae al binding AI */ }
  }
  // Fallback gratis: Workers AI (Llama). El binding AI se habilita en wrangler.toml.
  if (env.AI){
    try {
      const r = await env.AI.run("@cf/meta/llama-3.3-70b-instruct-fp8-fast", {
        messages: [{ role: "system", content: extra ? system + "\n" + extra : system }].concat(mensajes),
        max_tokens: 280
      });
      const t = (r && (r.response || "")).trim();
      if (t) return sanearRespuestaIA(t);
    } catch (e) { /* sin IA disponible */ }
  }
  return null;
}

/* ============ Vendedor/recepcionista IA de WhatsApp (por academia) ============
   Atiende por WhatsApp a los LEADS de una academia (distinto del soporte del producto,
   que atiende a duenos/alumnos DENTRO de Batuta). Reusa llamarClaudeOnboarding (Claude
   Haiku con prompt-cache + fallback Workers AI + saneo de estilo de marca). Compliance:
   el prompt PROHIBE promesas de resultado/ingresos (regla permanente de la casa). */
const WA_VENDEDOR_SYS =
  "Eres el asistente de recepcion de una academia, atendiendo por WhatsApp a una persona interesada en tomar clases. " +
  "Tu trabajo: dar la bienvenida, entender que quiere aprender, responder precios y horarios con los DATOS de abajo, y motivarla a agendar una clase de prueba. El profesor humano cierra; tu abres la puerta.\n" +
  "TRANSPARENCIA (obligatorio): eres un asistente virtual, no una persona. Si te preguntan si eres humano, un bot o una IA, dilo de frente y sin rodeos, y ofrece pasar la conversacion a una persona. Nunca digas ni des a entender que eres el profesor o una persona del equipo.\n" +
  "ESTILO (estricto): espanol claro y calido, de tu, maximo 3 frases por mensaje, directo, sin relleno. Sin em dash. Sin signos de apertura invertidos (nada de ¿ ni ¡, solo los de cierre). Sin markdown, sin asteriscos, sin vinetas: es WhatsApp, texto plano. Un emoji ocasional esta bien, con mesura. Nunca suenes a robot.\n" +
  "QUE HACES: saludas (por el nombre si lo tienes), preguntas que le gustaria aprender, respondes cursos/precios/horarios SOLO desde los DATOS, e invitas a agendar una clase de prueba o a dejar sus datos para que el profesor le escriba.\n" +
  "REGLAS DURAS: NUNCA prometes resultados, progreso garantizado ni ingresos (nada de 'vas a aprender en X semanas' ni 'garantizado'). NUNCA inventas precios, horarios, promos ni cursos que no esten en los DATOS. NUNCA cierras un pago ni pides datos de tarjeta por el chat: para pagar, el profesor coordina. NUNCA hablas mal de nadie, tono positivo. Si es un reclamo, un problema serio o piden hablar con una persona: di que el profesor le escribe en breve, no improvises. Si algo no esta en los DATOS, dilo con honestidad y ofrece que el profesor lo confirme.\n" +
  "CIERRE: siempre dejas una puerta abierta concreta (agendar prueba o 'el profesor te escribe hoy'). Nunca cierras en seco.";

async function contextoVentaWA(env, tenant, cfg){
  let lineas = "DATOS DE ESTA ACADEMIA:\n- Nombre: " + (tenant.academia || "la academia") + "\n";
  const cursos = String((cfg && cfg.cursos) || "").split(",").map(s => s.trim()).filter(Boolean);
  if (cursos.length) lineas += "- Cursos que ensena: " + cursos.join(", ") + "\n";
  try {
    const paq = await loadPaquetes(env, tenant.id);
    const precios = await loadPrecios(env, tenant.id);
    const items = (paq.list || []).map(nombre => {
      const pk = paq.map[nombre] || {};
      const monto = precios[nombre] != null ? precios[nombre] : null;
      const detalle = pk.ilim ? "mensualidad" : (pk.clases + " clases");
      return "  - " + nombre + " (" + detalle + ")" + (monto ? " por S/ " + monto : "");
    });
    if (items.length) lineas += "- Precios y paquetes:\n" + items.join("\n") + "\n";
  } catch (e) {}
  const waProfe = (cfg && cfg.whatsapp_profe) || tenant.whatsapp || "";
  if (waProfe) lineas += "- WhatsApp del profesor (por si derivas): " + waProfe + "\n";
  /* Base de conocimiento libre editable por el dueno (Ajustes > WhatsApp): FAQ, promos,
     politicas, cualquier dato que el asistente deba saber y que no salga de cursos/precios. */
  const kb = String((cfg && cfg.wa_kb) || "").trim();
  if (kb) lineas += "- Informacion adicional que te dio la academia (usala como fuente):\n" + kb.slice(0, 2000) + "\n";
  lineas += "Si algun dato viene vacio, no lo menciones: ofrece que el profesor lo confirme.";
  return lineas;
}

/* ============ Voz editable del asistente (tono + instrucciones libres por tenant) ============
   El dueno elige un tono y escribe instrucciones desde Ajustes > WhatsApp. Este bloque se
   inyecta al system prompt del vendedor IA en CADA llamada (manda sobre el estilo por defecto,
   nunca sobre las REGLAS DURAS de compliance). Vacio si el dueno no configuro nada. */
const WA_TONOS = {
  cercano: "Tono cercano y calido, como quien recibe a un amigo. Trato de tu, con calidez y cero acartonamiento.",
  formal:  "Tono formal y profesional, con respeto y cortesia. Nada de jerga ni emojis.",
  directo: "Tono directo y breve, al grano, sin rodeos ni relleno. Frases cortas.",
  cordial: "Tono cordial y amable, con buena onda y una sonrisa en el texto. Un emoji ocasional bienvenido.",
  serio:   "Tono serio y sobrio, sin bromas y sin emojis. Profesional y mesurado."
};
function bloqueVozWA(cfg){
  const tono = WA_TONOS[String((cfg && cfg.wa_tono) || "").trim()] || "";
  const instr = String((cfg && cfg.wa_instrucciones) || "").trim().slice(0, 800);
  if (!tono && !instr) return "";
  let b = "\nVOZ DE ESTA ACADEMIA (respetala siempre; manda sobre el estilo por defecto, jamas sobre las REGLAS DURAS):";
  if (tono) b += "\n- " + tono;
  if (instr) b += "\n- Instrucciones del dueno: " + instr;
  return b;
}

/* ============ Sugerencias del asistente (modo "sugerencias": IA propone, el staff envia) ============
   Cuando el tenant elige modo 'sugerencias', la IA arma el borrador pero NO lo envia: se guarda
   aqui para que el dueno lo revise, copie y mande a mano desde su WhatsApp. Es la version segura
   y sin bandeja-en-vivo (esa llega con Meta aprobado, Parte B del plan). */
let WA_SUG_OK = false;
async function ensureWaSugSchema(env){
  if (WA_SUG_OK) return;
  try {
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS wa_sugerencia (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, telefono TEXT NOT NULL, nombre TEXT DEFAULT '', mensaje TEXT DEFAULT '', borrador TEXT DEFAULT '', estado TEXT DEFAULT 'pendiente', creado TEXT DEFAULT '')"
    ).run();
    await env.DB.prepare("CREATE INDEX IF NOT EXISTS idx_wa_sug_tenant ON wa_sugerencia (tenant_id, estado, creado)").run();
    WA_SUG_OK = true;
  } catch (e) {}
}
async function waSugerenciaGuardar(env, tenantId, telefono, nombre, mensaje, borrador){
  try {
    await ensureWaSugSchema(env);
    await env.DB.prepare(
      "INSERT INTO wa_sugerencia (id, tenant_id, telefono, nombre, mensaje, borrador, estado, creado) VALUES (?1,?2,?3,?4,?5,?6,'pendiente',?7)"
    ).bind(crypto.randomUUID(), tenantId, telefono, String(nombre || "").slice(0, 80), String(mensaje || "").slice(0, 500), String(borrador || "").slice(0, 1500), new Date().toISOString()).run();
  } catch (e) {}
}

/* Historial rolling de la conversacion WA por (tenant, telefono), ultimos ~8 turnos. */
async function waHistorialCargar(env, tenantId, telefono){
  try {
    const row = await env.DB.prepare("SELECT historial FROM wa_conv WHERE tenant_id = ?1 AND telefono = ?2").bind(tenantId, telefono).first();
    if (!row || !row.historial) return [];
    const arr = JSON.parse(row.historial);
    return Array.isArray(arr) ? arr.slice(-8) : [];
  } catch (e) { return []; }
}
async function waHistorialGuardar(env, tenantId, telefono, mensajes){
  try {
    const recorte = JSON.stringify((mensajes || []).slice(-8));
    await env.DB.prepare(
      "INSERT INTO wa_conv (tenant_id, telefono, historial, actualizado) VALUES (?1,?2,?3,?4) " +
      "ON CONFLICT(tenant_id, telefono) DO UPDATE SET historial = ?3, actualizado = ?4"
    ).bind(tenantId, telefono, recorte, new Date().toISOString()).run();
  } catch (e) {}
}

/* ============ Cupo de conversaciones del asistente WA (freemium 23-jul-2026) ============
   Gratis = 20 de POR VIDA (periodo 'total', la probadita que engancha); pago = por MES
   (PLAN_CONV_CAP). Una "conversacion" = ventana de 24h por telefono (no cada mensaje). Es lo
   que gatea el asistente por plan y protege el piso de 60% de margen. */
let WA_USO_OK = false;
async function ensureWaUsoSchema(env){
  if (WA_USO_OK) return;
  try {
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS wa_uso (tenant_id TEXT NOT NULL, periodo TEXT NOT NULL, usados INTEGER DEFAULT 0, actualizado TEXT DEFAULT '', PRIMARY KEY (tenant_id, periodo))"
    ).run();
    WA_USO_OK = true;
  } catch (e) {}
}
function waPlanEfectivo(tW){ const p = (tW && tW.plan) || ""; return (!p || (tW && tW.estado) === "vencido") ? "gratis" : p; }
/* Packs (20-ago-2026): TODO periodo es mensual. Las 5 de la base y las compradas se
   resetean el 1 de cada mes; ya no existe la bolsa "de por vida" del plan gratis viejo. */
function waPeriodo(){ return mesLima(); }
/* Es conversacion NUEVA (nueva ventana de 24h)? Solo las nuevas consumen cupo; las
   continuaciones dentro de las 24h no. Se mide con wa_conv.actualizado (aun no reescrito). */
async function waEsNuevaConversacion(env, tenantId, telefono){
  try {
    const row = await env.DB.prepare("SELECT actualizado FROM wa_conv WHERE tenant_id = ?1 AND telefono = ?2").bind(tenantId, telefono).first();
    if (!row || !row.actualizado) return true;
    const last = Date.parse(row.actualizado);
    if (!last) return true;
    return (Date.now() - last) > 24 * 3600 * 1000;
  } catch (e) { return true; }
}
/* Consume 1 conversacion del cupo del plan. Atomico (usados < cap en el WHERE). Devuelve
   {ok, usados, cap}: ok=false = cupo agotado (no responder con IA). Fail-open ante error DB. */
async function waConsumirConversacion(env, tenantId, plan){
  await ensureWaUsoSchema(env);
  const periodo = waPeriodo(), cap = await convCapDe(env, tenantId, plan === "gratis", plan), ahora = new Date().toISOString();
  try {
    await env.DB.prepare("INSERT OR IGNORE INTO wa_uso (tenant_id, periodo, usados, actualizado) VALUES (?1, ?2, 0, ?3)").bind(tenantId, periodo, ahora).run();
    const r = await env.DB.prepare("UPDATE wa_uso SET usados = usados + 1, actualizado = ?4 WHERE tenant_id = ?1 AND periodo = ?2 AND usados < ?3").bind(tenantId, periodo, cap, ahora).run();
    const ok = !!(r.meta && r.meta.changes === 1);
    const row = await env.DB.prepare("SELECT usados FROM wa_uso WHERE tenant_id = ?1 AND periodo = ?2").bind(tenantId, periodo).first();
    return { ok, usados: row ? Number(row.usados) : 0, cap };
  } catch (e) { return { ok: true, usados: 0, cap }; }
}
/* Uso actual del cupo (para el panel via /me), sin consumir. */
async function waUsoActual(env, tenantId, plan){
  try {
    await ensureWaUsoSchema(env);
    const periodo = waPeriodo(), cap = await convCapDe(env, tenantId, plan === "gratis", plan);
    const row = await env.DB.prepare("SELECT usados FROM wa_uso WHERE tenant_id = ?1 AND periodo = ?2").bind(tenantId, periodo).first();
    return { usados: row ? Number(row.usados) : 0, cap, periodo, plan };
  } catch (e) { return { usados: 0, cap: BASE_LIMITES.ia, periodo: waPeriodo(), plan }; }
}

/* ============ Asistente-cliente para NEGOCIOS sueltos (no-academia) — AISLADO, default OFF ============
   CAMINO A del "Configurador de WhatsApp con IA" (S/890): reusa la MISMA WABA de Batuta y el
   MISMO webhook ya vivo, pero rutea los numeros dados de alta como "negocio" a una rama propia
   con KB de TEXTO LIBRE (servicios/precios/FAQ/reglas) y system prompt generico. NO toca la
   logica de academias ni la de cobros: si el numero no esta en wa_negocio, esta rama no hace
   nada y sigue el flujo de academia intacto. Mismo espiritu de aislamiento que el modulo de
   Meta Ads. Compliance de la casa: el prompt PROHIBE promesas de resultado/ingresos, inventar
   datos y cerrar pagos/pedir tarjeta por chat. */
let NEG_SCHEMA_OK = false;
async function ensureNegocioSchema(env){
  if (NEG_SCHEMA_OK) return;
  try {
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS wa_negocio (id TEXT PRIMARY KEY, nombre TEXT NOT NULL, phone_id TEXT NOT NULL, enabled TEXT DEFAULT 'off', kb TEXT DEFAULT '', cap_mes INTEGER DEFAULT 1000, creado TEXT DEFAULT '', actualizado TEXT DEFAULT '')"
    ).run();
    await env.DB.prepare("CREATE UNIQUE INDEX IF NOT EXISTS idx_wa_negocio_phone ON wa_negocio (phone_id)").run();
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS wa_negocio_lead (negocio_id TEXT NOT NULL, telefono TEXT NOT NULL, nombre TEXT DEFAULT '', ultimo TEXT DEFAULT '', actualizado TEXT DEFAULT '', PRIMARY KEY (negocio_id, telefono))"
    ).run();
    /* pausa por chat (bandeja 10-ago-2026): 'on' = la IA se calla en ese chat y responde Andres
       a mano desde la bandeja. ALTER idempotente: falla en silencio si la columna ya existe. */
    try { await env.DB.prepare("ALTER TABLE wa_negocio_lead ADD COLUMN pausa TEXT DEFAULT ''").run(); } catch (e) {}
    NEG_SCHEMA_OK = true;
  } catch (e) {}
}

/* System prompt FIJO del asistente de negocio (va con cache_control en llamarClaudeOnboarding;
   la KB y la voz por-negocio viajan en el bloque de sesion, sin cache). Generalizado a
   "negocio" (no "academia"): recepcionista/vendedor que abre la puerta, el dueno cierra. */
const WA_NEGOCIO_SYS =
  "Eres el asistente por WhatsApp de un negocio, atendiendo a un cliente que escribe. " +
  "Tu trabajo: saludar, entender que necesita, responder con los DATOS de abajo (servicios, precios, preguntas frecuentes) y seguir las REGLAS del negocio para agendar una visita, pedir fotos o medidas, o derivar al dueno cuando toque. Tu abres la puerta, el dueno cierra.\n" +
  "ESTILO (estricto): espanol claro y calido, de tu, maximo 3 frases por mensaje, directo, sin relleno. Sin em dash. Sin signos de apertura invertidos (nada de un ¿ ni un ¡ al inicio, solo los de cierre). Sin markdown, sin asteriscos, sin vinetas ni dos puntos de titulo: es WhatsApp, texto plano. Un emoji ocasional con mesura. Habla con la VOZ que te indican los DATOS. Nunca suenes a robot ni a formulario.\n" +
  "REGLAS DURAS (no negociables): NUNCA prometes resultados, plazos garantizados ni ingresos. NUNCA inventas precios, datos, promos ni servicios que no esten en los DATOS: si no lo sabes, dilo con honestidad y ofrece que el dueno lo confirme. NUNCA cierras un pago ni pides datos de tarjeta, cuenta bancaria ni claves por el chat: para pagar, el dueno coordina. NUNCA hablas mal de nadie, tono positivo. Si es un reclamo serio o piden hablar con una persona, di que el dueno le escribe en breve y no improvises.\n" +
  "CIERRE: siempre dejas una puerta abierta concreta segun las REGLAS (agendar, mandar fotos o medidas, o 'el dueno te escribe'). Nunca cierras en seco.";

function negocioKbParse(kbStr){
  if (!kbStr) return {};
  try { const o = JSON.parse(kbStr); return (o && typeof o === "object") ? o : {}; } catch (e) { return {}; }
}

/* Saneo de estilo EXTRA solo para la rama negocio (no toca sanearRespuestaIA, que es compartido
   con el vendedor de academia). Aplica las reglas duras del "Configurador": NUNCA em dash, NUNCA
   markdown/vinetas. Belt-and-suspenders sobre lo que el prompt ya pide, por si el modelo lo ignora. */
function negocioLimpiarEstilo(t){
  if (!t) return t;
  return sanearRespuestaIA(String(t))
    .replace(/\s*[—–]\s*/g, ", ")        // em/en dash -> coma (regla de la casa: nunca em dash)
    .replace(/\*\*(.*?)\*\*/g, "$1")     // **negrita** -> plano
    .replace(/\*(.*?)\*/g, "$1")          // *cursiva* -> plano
    .replace(/[*_`>#~]/g, "")             // restos de markdown
    .replace(/^\s*[-•]\s+/gm, "")         // vinetas al inicio de linea
    .replace(/\s{2,}/g, " ")
    .trim();
}

/* Arma el bloque DATOS del negocio a partir de su KB (JSON de texto libre editable por cliente).
   Todo campo vacio se omite (regla: no menciones lo que no tienes). */
function contextoNegocioWA(neg, kb, nombreCliente){
  const b = kb || {};
  let l = "DATOS DEL NEGOCIO:\n- Nombre: " + (b.negocio || (neg && neg.nombre) || "el negocio") + "\n";
  if (b.rubro) l += "- Rubro: " + b.rubro + "\n";
  if (b.voz) l += "- Voz con la que hablas (imitala, es la del dueno): " + b.voz + "\n";
  const serv = Array.isArray(b.servicios) ? b.servicios : [];
  if (serv.length){
    l += "- Servicios y precios:\n";
    for (const s of serv){
      if (typeof s === "string"){ l += "  - " + s + "\n"; continue; }
      const nom = (s && (s.nombre || s.servicio)) || "";
      const pre = (s && s.precio != null && s.precio !== "") ? (" — " + s.precio) : "";
      const det = (s && s.detalle) ? (" (" + s.detalle + ")") : "";
      if (nom) l += "  - " + nom + pre + det + "\n";
    }
  }
  const faq = Array.isArray(b.faq) ? b.faq : [];
  if (faq.length){
    l += "- Preguntas frecuentes:\n";
    for (const f of faq){
      const q = (f && (f.q || f.pregunta)) || ""; const a = (f && (f.a || f.respuesta)) || "";
      if (q && a) l += "  - " + q + " -> " + a + "\n";
    }
  }
  const reglas = Array.isArray(b.reglas) ? b.reglas : [];
  if (reglas.length){
    l += "- Reglas de cuando agendar visita, pedir fotos o medidas, o derivar al dueno:\n";
    for (const r of reglas) if (r) l += "  - " + r + "\n";
  }
  if (b.horario) l += "- Horario de atencion: " + b.horario + "\n";
  if (b.zona) l += "- Zona o cobertura: " + b.zona + "\n";
  if (b.derivar_a) l += "- WhatsApp del dueno (por si derivas): " + b.derivar_a + "\n";
  if (b.cierre) l += "- Como cerrar cada mensaje: " + b.cierre + "\n";
  if (nombreCliente) l += "- El cliente se llama " + String(nombreCliente).split(" ")[0] + ".\n";
  l += "Si un dato no esta aqui, no lo inventes: dilo y ofrece que el dueno lo confirme.";
  return l;
}

/* Resuelve el negocio dueno de un phone_number_id (o null si ese numero no es un negocio). */
async function negocioPorPhone(env, phoneId){
  await ensureNegocioSchema(env);
  try {
    return await env.DB.prepare("SELECT id, nombre, phone_id, enabled, kb, cap_mes FROM wa_negocio WHERE phone_id = ?1").bind(String(phoneId)).first();
  } catch (e) { return null; }
}

/* Registra/actualiza el lead entrante del negocio (una fila por telefono) para que el dueno lo vea. */
async function negocioLeadUpsert(env, negId, from, nombre, texto){
  try {
    await ensureNegocioSchema(env);
    const ahora = new Date().toISOString();
    await env.DB.prepare(
      "INSERT INTO wa_negocio_lead (negocio_id, telefono, nombre, ultimo, actualizado) VALUES (?1,?2,?3,?4,?5) " +
      "ON CONFLICT(negocio_id, telefono) DO UPDATE SET nombre = CASE WHEN ?3 != '' THEN ?3 ELSE nombre END, ultimo = ?4, actualizado = ?5"
    ).bind(negId, from, String(nombre || "").slice(0, 80), String(texto || "").slice(0, 500), ahora).run();
  } catch (e) {}
}

/* Cupo MENSUAL de conversaciones por negocio (protege el costo de tokens del worker de Andres,
   ver "COSTO PARA ANDRES" del reporte). Reusa la tabla wa_uso con tenant sintetico 'neg:'+id.
   Atomico (usados < cap en el WHERE). Fail-open ante error de DB. */
async function negocioConsumirConv(env, negId, cap){
  await ensureWaUsoSchema(env);
  const tid = "neg:" + negId, periodo = mesLima(), ahora = new Date().toISOString(), tope = Number(cap) > 0 ? Number(cap) : 1000;
  try {
    await env.DB.prepare("INSERT OR IGNORE INTO wa_uso (tenant_id, periodo, usados, actualizado) VALUES (?1, ?2, 0, ?3)").bind(tid, periodo, ahora).run();
    const r = await env.DB.prepare("UPDATE wa_uso SET usados = usados + 1, actualizado = ?4 WHERE tenant_id = ?1 AND periodo = ?2 AND usados < ?3").bind(tid, periodo, tope, ahora).run();
    const ok = !!(r.meta && r.meta.changes === 1);
    const row = await env.DB.prepare("SELECT usados FROM wa_uso WHERE tenant_id = ?1 AND periodo = ?2").bind(tid, periodo).first();
    return { ok, usados: row ? Number(row.usados) : 0, cap: tope };
  } catch (e) { return { ok: true, usados: 0, cap: tope }; }
}

/* Maneja un mensaje entrante SI el numero es un negocio dado de alta. Devuelve:
   - false: el numero NO es un negocio -> el webhook sigue con el flujo de academia (sin cambios).
   - true : era un negocio (respondido, apagado, o sin cupo) -> el webhook NO sigue con academia.
   Es la UNICA integracion con el webhook existente y es un no-op mientras wa_negocio este vacia. */
async function manejarNegocioWA(env, { phoneId, from, texto, nombre }){
  let neg;
  try { neg = await negocioPorPhone(env, phoneId); } catch (e) { return false; }
  if (!neg) return false;                                   // no es negocio: sigue el flujo academia
  if (String(neg.enabled || "") !== "on") return true;      // dado de alta pero apagado: no responde
  // freno de abuso: max ~12 respuestas por cliente por hora (misma ventana horaria)
  if (await chatbotPasoTope(env, "neg:" + neg.id + ":" + from, 12)) return true;
  const kb = negocioKbParse(neg.kb);
  const synthTenant = "neg:" + neg.id;
  /* Chat NUEVO (primera vez que este telefono escribe a este negocio) -> UN aviso a Andres por
     correo, disparado por CODIGO (leccion 19-jul: nunca a criterio del modelo). No se repite
     por mensaje: solo cuando la fila del lead no existia. */
  let leadPrev = null;
  try { leadPrev = await env.DB.prepare("SELECT telefono, pausa FROM wa_negocio_lead WHERE negocio_id = ?1 AND telefono = ?2").bind(neg.id, from).first(); } catch (e) {}
  await negocioLeadUpsert(env, neg.id, from, nombre, texto);
  if (!leadPrev){
    try {
      await alertaCorreoAndres(env,
        "WhatsApp " + (neg.nombre || "negocio") + ": chat nuevo de " + (nombre || from),
        "Chat nuevo en la linea Cloud API.\n\nNegocio: " + (neg.nombre || neg.id) +
        "\nDe: " + (nombre ? nombre + " (" + from + ")" : from) +
        "\nMensaje: " + String(texto || "").slice(0, 500) +
        "\n\nBandeja (ver chat, responder a mano o pausar la IA):\nhttps://batuta.lat/app/su/bandeja");
    } catch (e) {}
  }
  /* Pausa por chat (bandeja): si Andres pauso este chat, la IA se calla. El mensaje igual
     queda en el historial para que la bandeja lo muestre. */
  if (leadPrev && String(leadPrev.pausa || "") === "on"){
    const previoP = await waHistorialCargar(env, synthTenant, from);
    await waHistorialGuardar(env, synthTenant, from, previoP.concat([{ role: "user", content: texto }]));
    return true;
  }
  // cupo mensual: solo las conversaciones NUEVAS (ventana de 24h) consumen. Al agotarse, el lead
  // ya quedo registrado y el dueno responde a mano (no se llama a la IA).
  const esConvNuevaNeg = await waEsNuevaConversacion(env, synthTenant, from);
  if (esConvNuevaNeg){
    const cupo = await negocioConsumirConv(env, neg.id, neg.cap_mes);
    if (!cupo.ok) return true;
  }
  const datos = contextoNegocioWA(neg, kb, nombre);
  const previo = await waHistorialCargar(env, synthTenant, from);
  const conversacion = previo.concat([{ role: "user", content: texto }]);
  // guarda el turno del cliente YA (aunque el envio falle, la bandeja lo muestra)
  await waHistorialGuardar(env, synthTenant, from, conversacion);
  let reply = await llamarClaudeOnboarding(env, WA_NEGOCIO_SYS, conversacion, datos, kb.modelo === "sonnet" ? "sonnet" : "");
  if (reply) reply = negocioLimpiarEstilo(reply); // regla dura negocio: sin em dash ni markdown
  if (!reply){
    // sin IA disponible: primer-toque calido de respaldo (no deja al cliente sin respuesta)
    reply = (nombre ? String(nombre).split(" ")[0] : "Hola") + ", gracias por escribir a " + (neg.nombre || "nosotros") + ". Cuentame que necesitas y te ayudo, o el dueno te escribe en breve.";
  }
  /* Misma transparencia algorítmica que en el asistente de academias (Ley 31814). */
  const salidaNeg = esConvNuevaNeg
    ? ("Te responde el asistente virtual de " + (neg.nombre || "este negocio") +
       ". Si prefieres hablar con una persona, escribe: quiero hablar con alguien.\n\n" + reply)
    : reply;
  const enviado = await enviarWhatsApp(env, phoneId, from, salidaNeg);
  if (enviado){
    await waHistorialGuardar(env, synthTenant, from, conversacion.concat([{ role: "assistant", content: reply }]));
  }
  return true;
}

/* ============ Meta Ads (Marketing API) por tenant — AISLADO, gated por secrets ============
   Cada academia conecta SU cuenta publicitaria via Facebook Login for Business (token System
   User, no expira). Requiere los secrets META_APP_ID / META_APP_SECRET / META_LOGIN_CONFIG_ID
   (los carga Andres al crear la app de Batuta en Meta). Sin ellos el modulo responde "no
   configurado" y el panel lo oculta. Las campanas se crean SIEMPRE en PAUSED (la academia las
   activa en Ads Manager: nunca se gasta plata sin su ok). Nada de esto toca la logica de cobros.
   Compliance: el objetivo es leads a la web del tenant; el copy nunca promete resultados. */
const META_GRAPH = "https://graph.facebook.com/v21.0";
function metaConfigurado(env){ return !!(env.META_APP_ID && env.META_APP_SECRET && env.META_LOGIN_CONFIG_ID); }

async function appsecretProof(token, appSecret){
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(appSecret),
    { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(token));
  return [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, "0")).join("");
}
/* Llamada firmada al Graph API. GET manda params en la query; POST en el body (x-www-form). */
async function metaFetch(env, token, path, opts){
  opts = opts || {};
  const method = opts.method || "GET";
  const proof = await appsecretProof(token, env.META_APP_SECRET);
  if (method === "GET"){
    const qs = new URLSearchParams(Object.assign({ access_token: token, appsecret_proof: proof }, opts.params || {}));
    const r = await fetch(META_GRAPH + path + (path.includes("?") ? "&" : "?") + qs.toString());
    const data = await r.json().catch(() => null);
    return { ok: r.ok, status: r.status, data, error: (data && data.error) || null };
  }
  const form = new URLSearchParams({ access_token: token, appsecret_proof: proof });
  const p = opts.params || {};
  for (const k of Object.keys(p)) form.set(k, typeof p[k] === "string" ? p[k] : JSON.stringify(p[k]));
  const r = await fetch(META_GRAPH + path, { method, body: form });
  const data = await r.json().catch(() => null);
  return { ok: r.ok, status: r.status, data, error: (data && data.error) || null };
}
async function metaConexion(env, tenantId){
  try { return await env.DB.prepare("SELECT * FROM meta_ads_conexion WHERE tenant_id = ?1").bind(tenantId).first(); }
  catch (e) { return null; }
}
/* Canjea el `code` de Facebook Login for Business por un token de larga duracion / System User,
   lista las cuentas publicitarias y paginas del usuario, y guarda la conexion del tenant. */
async function metaConectarTenant(env, tenantId, code, redirectUri){
  if (!metaConfigurado(env)) return { ok: false, error: "Meta Ads no esta configurado todavia." };
  const tokRes = await fetch(META_GRAPH + "/oauth/access_token?" + new URLSearchParams({
    client_id: env.META_APP_ID, client_secret: env.META_APP_SECRET,
    redirect_uri: redirectUri || (MARCA.dominio + "/app/meta/callback"), code: code
  }).toString());
  const tokData = await tokRes.json().catch(() => null);
  if (!tokRes.ok || !tokData || !tokData.access_token){
    return { ok: false, error: (tokData && tokData.error && tokData.error.message) || "No se pudo canjear el codigo con Meta." };
  }
  const token = tokData.access_token;
  const cuentasR = await metaFetch(env, token, "/me/adaccounts", { params: { fields: "account_id,id,name,account_status,currency,business" } });
  const paginasR = await metaFetch(env, token, "/me/accounts", { params: { fields: "id,name" } });
  const cuentas = (cuentasR.data && cuentasR.data.data) || [];
  const paginas = (paginasR.data && paginasR.data.data) || [];
  await env.DB.prepare(
    "INSERT INTO meta_ads_conexion (tenant_id, token, cuentas_json, paginas_json, actualizado) VALUES (?1,?2,?3,?4,?5) " +
    "ON CONFLICT(tenant_id) DO UPDATE SET token = ?2, cuentas_json = ?3, paginas_json = ?4, actualizado = ?5"
  ).bind(tenantId, token, JSON.stringify(cuentas), JSON.stringify(paginas), new Date().toISOString()).run();
  return { ok: true, cuentas, paginas };
}
/* Crea una campana de LEADS a la web del tenant: campaign -> adset -> creative -> ad, TODO en
   PAUSED. Devuelve los ids y el link a Ads Manager para que la academia revise y active.
   OJO (verificar la 1a vez contra la cuenta real de Andres via Graph API Explorer, segun el
   research): los nombres de campo de /adsets y /adcreatives son los documentados y estables,
   pero conviene una corrida de validacion antes de confiarla a un cliente. */
async function metaCrearCampana(env, conx, opts){
  const token = conx.token, act = conx.act_id;
  if (!token || !act) return { ok: false, error: "Falta conectar y elegir una cuenta publicitaria." };
  const nombre = String(opts.nombre || "Campana de leads").slice(0, 80);
  const budget = Math.max(100, Math.round((Number(opts.presupuesto_dia) || 20) * 100)); // centavos de la moneda
  // 1) campana
  const camp = await metaFetch(env, token, "/act_" + act + "/campaigns", { method: "POST", params: {
    name: nombre, objective: "OUTCOME_LEADS", special_ad_categories: [], status: "PAUSED" } });
  if (!camp.ok || !camp.data || !camp.data.id) return { ok: false, error: metaMsg(camp), paso: "campana" };
  const campaignId = camp.data.id;
  // 2) ad set (conversiones web optimizadas por LEAD, si hay pixel; si no, por alcance a landing)
  const promoted = conx.pixel_id ? { pixel_id: conx.pixel_id, custom_event_type: "LEAD" } : null;
  const adsetParams = {
    name: nombre + " - conjunto", campaign_id: campaignId, billing_event: "IMPRESSIONS",
    daily_budget: String(budget), bid_strategy: "LOWEST_COST_WITHOUT_CAP", status: "PAUSED",
    destination_type: "WEBSITE",
    optimization_goal: promoted ? "OFFSITE_CONVERSIONS" : "LINK_CLICKS",
    targeting: { geo_locations: { countries: [String(opts.pais || "PE")] }, age_min: 18, age_max: 65 }
  };
  if (promoted) adsetParams.promoted_object = promoted;
  const adset = await metaFetch(env, token, "/act_" + act + "/adsets", { method: "POST", params: adsetParams });
  if (!adset.ok || !adset.data || !adset.data.id) return { ok: false, error: metaMsg(adset), paso: "adset", campaignId };
  // 3) creativo (dark post via object_story_spec). Requiere la app en Live (error 1885183 si no).
  const link = String(opts.landing || (MARCA.dominio)).slice(0, 300);
  const creativeParams = { name: nombre + " - creativo", object_story_spec: {
    page_id: conx.page_id,
    link_data: { link: link, message: String(opts.copy || "").slice(0, 600), name: String(opts.titular || "").slice(0, 120),
      call_to_action: { type: "SIGN_UP", value: { link: link } } } } };
  const creative = await metaFetch(env, token, "/act_" + act + "/adcreatives", { method: "POST", params: creativeParams });
  if (!creative.ok || !creative.data || !creative.data.id) return { ok: false, error: metaMsg(creative), paso: "creativo", campaignId };
  // 4) ad
  const ad = await metaFetch(env, token, "/act_" + act + "/ads", { method: "POST", params: {
    name: nombre + " - anuncio", adset_id: adset.data.id, creative: { creative_id: creative.data.id }, status: "PAUSED" } });
  if (!ad.ok || !ad.data || !ad.data.id) return { ok: false, error: metaMsg(ad), paso: "ad", campaignId };
  return { ok: true, campaignId, adsetId: adset.data.id, creativeId: creative.data.id, adId: ad.data.id,
    adsManager: "https://www.facebook.com/adsmanager/manage/campaigns?act=" + act + "&selected_campaign_ids=" + campaignId };
}
function metaMsg(res){
  const e = res && res.error;
  if (!e) return "Error de Meta (" + (res && res.status) + ")";
  let m = e.error_user_msg || e.message || "Error de Meta";
  if (e.error_subcode === 1885183) m = "Tu app de Meta esta en modo desarrollo: pasala a Live para crear anuncios.";
  return m;
}
/* Soporte con IA (14-jul-2026): el asistente dejo de ser solo onboarding y ahora es el
   canal de soporte del producto. La cuota paso de VITALICIA a MENSUAL: la clave de
   onboarding_ia_uso lleva el mes, asi cada mes empieza de cero sin migrar nada (las filas
   viejas sin mes quedan huerfanas e inofensivas). Claves (review adversarial 14-jul):
   - admin:<profesor_id>:<mes> = POR PERSONA del equipo (dueno y cada profesor tienen su
     propia bolsa; fallback al tenant_id en sesiones T: legacy sin fila de profesor).
     Nota: en la demo publica todos comparten al dueno demo -> una sola bolsa, y eso es
     a proposito (freno de abuso del /app/demo).
   - alumno:<cuenta_id>:<mes> = por cuenta + un TECHO por tenant (alumnos:<tenant>:<mes>),
     porque el registro de alumnos es abierto y sin techo se acunarian cuentas frescas
     para bolsas nuevas. */
const ONBOARDING_LIMITE_ADMIN = 60;            // mensajes/mes por persona del equipo (tenant de 0-90 dias)
const ONBOARDING_LIMITE_ADMIN_90D = 30;        // idem, tenant con mas de 90 dias (decision Andres 14-jul-2026)
const ONBOARDING_LIMITE_ALUMNO = 15;           // mensajes/mes por cuenta de alumno
const ONBOARDING_LIMITE_ALUMNOS_TENANT = 150;  // techo mensual de TODOS los alumnos de un tenant
function mesActualUTC(){ return new Date().toISOString().slice(0, 7); }
/* El mes de LIMA. Los TOPES QUE VIVE UN CLIENTE ("5 conversaciones al mes") se cuentan en su
   mes, no en el de Greenwich: con el mes UTC, entre las 19:00 y medianoche del último día el
   cupo se reseteaba 5 horas antes de tiempo. Es la misma corrección que ya se hizo en la caja,
   que agrupa por `hoyLima().slice(0,7)`. Los LIBROS (comisiones, pagos de MP) siguen en UTC a
   propósito: son registros, no cupos, y moverlos reescribiría historia. */
function mesLima(){ return hoyLima().slice(0, 7); }
/* Paquetes de mensajes EXTRA del soporte IA (precios de Andres, 14-jul-2026): 30->S/5,
   60->S/10, 120->S/15. Dos vias de venta: self-service en el chat del panel (checkout MP
   de pago unico, tabla packs_compras) o manual por WhatsApp (su/mensajes-pack). Se
   consumen SOLO cuando la bolsa mensual del tenant ya se agoto. Tabla mensajes_extra por
   (tenant, mes): comprados vs usados. */
const PACKS_MENSAJES = { "5": 30, "10": 60, "15": 120 };
let MENSAJES_EXTRA_OK = false;
async function ensureMensajesExtraSchema(env){
  if (MENSAJES_EXTRA_OK) return;
  try {
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS mensajes_extra (tenant_id TEXT NOT NULL, mes TEXT NOT NULL, comprados INTEGER DEFAULT 0, usados INTEGER DEFAULT 0, actualizado TEXT DEFAULT '', PRIMARY KEY (tenant_id, mes))"
    ).run();
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS packs_compras (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, pack TEXT NOT NULL, mensajes INTEGER NOT NULL, monto INTEGER NOT NULL, estado TEXT NOT NULL, fecha TEXT DEFAULT '', mp_payment_id TEXT DEFAULT '')"
    ).run();
    MENSAJES_EXTRA_OK = true;
  } catch (e) {}
}
/* Suma mensajes extra a la bolsa del mes EN CURSO (compra confirmada, cualquiera de las vias). */
async function acreditarMensajesExtra(env, tenantId, cant){
  await ensureMensajesExtraSchema(env);
  await env.DB.prepare(
    "INSERT INTO mensajes_extra (tenant_id, mes, comprados, usados, actualizado) VALUES (?1, ?2, ?3, 0, ?4) " +
    "ON CONFLICT(tenant_id, mes) DO UPDATE SET comprados = comprados + ?3, actualizado = ?4"
  ).bind(tenantId, mesActualUTC(), cant, new Date().toISOString()).run();
}
/* Saldo de mensajes extra del mes en curso (para el contador del chat). */
async function saldoMensajesExtra(env, tenantId){
  try {
    await ensureMensajesExtraSchema(env);
    const r = await env.DB.prepare(
      "SELECT comprados - usados AS s FROM mensajes_extra WHERE tenant_id = ?1 AND mes = ?2"
    ).bind(tenantId, mesActualUTC()).first();
    return r ? Math.max(0, Number(r.s) || 0) : 0;
  } catch (e) { return 0; }
}
/* Confirma una compra self-service de pack y acredita. ATOMICO anti-doble-credito: el
   UPDATE solo pasa de 'iniciada' a 'pagada' una vez (changes=1); el webhook de MP y la
   confirmacion al volver al panel pueden llegar ambos y solo uno acredita. */
async function confirmarPackCompra(env, compraId, paymentId){
  await ensureMensajesExtraSchema(env);
  const upd = await env.DB.prepare(
    "UPDATE packs_compras SET estado = 'pagada', mp_payment_id = ?2, fecha = ?3 WHERE id = ?1 AND estado = 'iniciada'"
  ).bind(compraId, String(paymentId || ""), new Date().toISOString()).run();
  if (!(upd.meta && upd.meta.changes === 1)) return null;
  const compra = await env.DB.prepare("SELECT * FROM packs_compras WHERE id = ?1").bind(compraId).first();
  if (!compra) return null;
  await acreditarMensajesExtra(env, compra.tenant_id, Number(compra.mensajes) || 0);
  return compra;
}
/* Consume 1 mensaje extra del mes en curso si queda saldo. Atomico (usados < comprados en
   el WHERE); meta.changes=1 = habia saldo y se descontó. */
async function consumirMensajeExtra(env, tenantId){
  try {
    await ensureMensajesExtraSchema(env);
    const r = await env.DB.prepare(
      "UPDATE mensajes_extra SET usados = usados + 1, actualizado = ?3 WHERE tenant_id = ?1 AND mes = ?2 AND usados < comprados"
    ).bind(tenantId, mesActualUTC(), new Date().toISOString()).run();
    return !!(r.meta && r.meta.changes === 1);
  } catch (e) { return false; }
}
/* ---------- Plan ANUAL (15-jul-2026): pago unico via checkout preference ----------
   Mismo patron anti-doble-credito de los packs: iniciada -> pagada una sola vez
   (el webhook y la confirmacion al volver pueden llegar ambos; solo uno acredita). */
let ANUAL_OK = false;
async function ensureAnualSchema(env){
  if (ANUAL_OK) return;
  try {
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS anual_compras (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, plan TEXT NOT NULL, monto INTEGER NOT NULL, estado TEXT NOT NULL, fecha TEXT DEFAULT '', mp_payment_id TEXT DEFAULT '')"
    ).run();
    ANUAL_OK = true;
  } catch (e) {}
}
/* Acredita 12 meses: estado 'trial' con trial_hasta a +365d desde hoy (o desde el fin del
   trial vigente si aun es futuro) + nurture_paso=9 (fuera del nurture, mecanismo del año
   fundador). Si habia preapproval mensual vivo, se CANCELA en MP (anti doble cobro). */
async function acreditarPlanAnual(env, tenantId, plan){
  const t = await env.DB.prepare("SELECT * FROM tenants WHERE id = ?1").bind(tenantId).first();
  if (!t) return null;
  if (t.mp_preapproval_id && env.MP_ACCESS_TOKEN){
    try { await mpFetch(env, "/preapproval/" + encodeURIComponent(t.mp_preapproval_id), { method: "PUT", body: { status: "cancelled" } }); } catch (e) {}
  }
  const base = Math.max(Date.now(), Date.parse(t.trial_hasta) || 0);
  const hasta = new Date(base + 365 * 86400000).toISOString();
  try { await env.DB.prepare("ALTER TABLE tenants ADD COLUMN nurture_paso INTEGER DEFAULT 0").run(); } catch (e) {}
  await env.DB.prepare(
    "UPDATE tenants SET plan = ?1, estado = 'trial', trial_hasta = ?2, nurture_paso = 9, mp_preapproval_id = '', mp_sub_status = 'anual' WHERE id = ?3"
  ).bind(plan, hasta, tenantId).run();
  return hasta;
}
async function confirmarAnualCompra(env, compraId, paymentId){
  await ensureAnualSchema(env);
  const upd = await env.DB.prepare(
    "UPDATE anual_compras SET estado = 'pagada', mp_payment_id = ?2, fecha = ?3 WHERE id = ?1 AND estado = 'iniciada'"
  ).bind(compraId, String(paymentId || ""), new Date().toISOString()).run();
  if (!(upd.meta && upd.meta.changes === 1)) return null;
  const compra = await env.DB.prepare("SELECT * FROM anual_compras WHERE id = ?1").bind(compraId).first();
  if (!compra) return null;
  const hasta = await acreditarPlanAnual(env, compra.tenant_id, compra.plan);
  return hasta ? Object.assign({}, compra, { hasta }) : null;
}

/* ---------- Afiliados v1 (16-jul-2026, terminos aprobados por Andres) ----------
   30% de cada mensualidad pagada del referido, tope 12 meses por tenant, reversa si hay refund.
   Atribucion: ?ref= en cualquier pagina -> cookie batuta_ref (60 dias) -> tenants.ref_code
   (inmutable, se escribe SOLO en el INSERT del registro) + fila en `referidos`.
   Ledger: `comisiones` es la fuente de verdad (tipo comision/reversa/payout_credito/payout_paypal;
   saldo del afiliado = SUM(monto), sin contador que se desvie).
   Payout AUTOMATICO (regla de Andres: nada de Yape manual):
   - Afiliado que es tenant de Batuta: su saldo >= S/50 se descuenta solo de su siguiente
     cobro de MP (PUT al preapproval; el webhook del pago descontado lo liquida y restaura).
   - Afiliado cash: PayPal Payouts, DETRAS del flag env.PAYPAL_PAYOUTS_ON (hasta que Andres
     confirme la aprobacion del API en su cuenta business).
   Alta manual via su/afiliado; los tenants que comparten su slug se auto-registran como
   afiliados al traer su primer referido. */
const AFILIADO_COMISION = 0.30;
/* 🔴 22-ago-2026 · lo que ESE tenant paga al mes, de verdad. El 21-ago se arregló acá abajo
   (`otorgarComision`) porque con el modelo de packs el plan es 'base' y `PLANES` no lo tiene,
   así que daba 0 y el afiliado se quedaba sin comisión en silencio. El mismo `PLANES[plan]`
   seguía vivo en las DOS funciones hermanas: `aplicarCreditosAfiliados` (que por eso NUNCA
   pagaba a un afiliado-tenant: precio 0 → `continue`) y `liquidarCreditoAfiliado`, que le
   restaura el precio a su cobro de MercadoPago — o sea que ahí el número equivocado le cambia
   lo que se le cobra. Una regla, un sitio. */
async function montoMensualTenant(env, tenant){
  if (!tenant) return 0;
  try { const m = Number((await packsDe(env, tenant.id)).monto) || 0; if (m > 0) return m; } catch (e) {}
  return Number(PLANES[tenant.plan]) || 0;   // tenants legacy sin migrar
}
const AFILIADO_TOPE_MESES = 12;
const AFILIADO_PAYOUT_MIN = 50; // S/. saldo minimo para disparar payout (evita micropagos)
let AFILIADOS_OK = false;
async function ensureAfiliadosSchema(env){
  if (AFILIADOS_OK) return;
  try {
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS afiliados (codigo TEXT PRIMARY KEY, nombre TEXT NOT NULL, contacto TEXT DEFAULT '', email_paypal TEXT DEFAULT '', tenant_id TEXT DEFAULT '', token_panel TEXT NOT NULL, clics INTEGER DEFAULT 0, descuento_pen REAL DEFAULT 0, creado TEXT DEFAULT '')"
    ).run();
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS referidos (tenant_id TEXT PRIMARY KEY, codigo TEXT NOT NULL, fecha TEXT DEFAULT '')"
    ).run();
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS comisiones (id TEXT PRIMARY KEY, codigo TEXT NOT NULL, tenant_id TEXT DEFAULT '', tipo TEXT NOT NULL, mes TEXT DEFAULT '', mp_payment_id TEXT DEFAULT '', mp_pago_id TEXT DEFAULT '', monto_base REAL DEFAULT 0, monto REAL NOT NULL, fecha TEXT DEFAULT '')"
    ).run();
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS afiliado_solicitudes (id TEXT PRIMARY KEY, nombre TEXT DEFAULT '', email TEXT DEFAULT '', whatsapp TEXT DEFAULT '', paypal TEXT DEFAULT '', canal TEXT DEFAULT '', fecha TEXT DEFAULT '')"
    ).run();
    try { await env.DB.prepare("ALTER TABLE tenants ADD COLUMN ref_code TEXT DEFAULT ''").run(); } catch (e) { /* ya existe */ }
    /* Migracion best-effort del piloto viejo (afiliados_ext, liquidacion manual): una vez. */
    try {
      const viejos = await env.DB.prepare("SELECT codigo, nombre, whatsapp, email, creado FROM afiliados_ext").all();
      for (const v of (viejos.results || [])){
        await env.DB.prepare(
          "INSERT INTO afiliados (codigo, nombre, contacto, token_panel, creado) VALUES (?1,?2,?3,?4,?5) ON CONFLICT(codigo) DO NOTHING"
        ).bind(v.codigo, v.nombre, [v.whatsapp, v.email].filter(Boolean).join(" · "), randHex(16), v.creado || new Date().toISOString()).run();
      }
    } catch (e) { /* afiliados_ext puede no existir */ }
    AFILIADOS_OK = true;
  } catch (e) {}
}
function normRefCode(s){ return String(s || "").trim().toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60); }
/* De donde sale el codigo de afiliado de un registro: lo explicito (?ref= / body.ref) y si no
   la cookie `batuta_ref` (60 dias) que siembra cualquier pagina de batuta.lat.
   🐛 23-ago-2026: esto vivia SUELTO dentro del registro por correo. Batuta tiene DOS puertas
   (correo y "Registrarme con Google") y la de Google nacio sin ello: el referido entraba, la
   academia se creaba y la comision del afiliado (30% x 12 meses) se perdia en silencio. La
   atribucion es INMUTABLE, asi que despues no habia forma de recuperarla.
   El decodeURIComponent va protegido: una cookie con un `%` suelto tiraba 500 en el registro. */
function refDePeticion(request, explicito){
  let code = normRefCode(explicito);
  if (!code){
    const m = /(?:^|;\s*)batuta_ref=([^;]+)/.exec((request && request.headers && request.headers.get("cookie")) || "");
    if (m){ try { code = normRefCode(decodeURIComponent(m[1])); } catch (e) { code = normRefCode(m[1]); } }
  }
  return code;
}
async function afiliadoPorCodigo(env, codigo){
  const c = normRefCode(codigo);
  if (!c) return null;
  await ensureAfiliadosSchema(env);
  return env.DB.prepare("SELECT * FROM afiliados WHERE codigo = ?1").bind(c).first().catch(() => null);
}
async function saldoAfiliado(env, codigo){
  const r = await env.DB.prepare("SELECT COALESCE(SUM(monto),0) AS s FROM comisiones WHERE codigo = ?1").bind(codigo).first().catch(() => null);
  return Math.round(((r && Number(r.s)) || 0) * 100) / 100;
}
/* Vincula un tenant RECIEN creado con su afiliado (fila en `referidos`, inmutable por PK).
   Si el codigo es el slug de otro tenant y aun no hay afiliado, ese tenant se auto-registra
   como afiliado (payout = credito automatico en su propio cobro de MP). */
async function registrarReferido(env, tenantId, refCode){
  const code = normRefCode(refCode);
  if (!code || !tenantId) return null;
  await ensureAfiliadosSchema(env);
  let af = await afiliadoPorCodigo(env, code);
  if (!af){
    const tDueno = await env.DB.prepare("SELECT id, slug, academia, email, whatsapp FROM tenants WHERE slug = ?1").bind(code).first().catch(() => null);
    if (!tDueno || tDueno.id === tenantId) return null;
    await env.DB.prepare(
      "INSERT INTO afiliados (codigo, nombre, contacto, tenant_id, token_panel, creado) VALUES (?1,?2,?3,?4,?5,?6) ON CONFLICT(codigo) DO NOTHING"
    ).bind(code, tDueno.academia || code, [tDueno.email, tDueno.whatsapp].filter(Boolean).join(" · "), tDueno.id, randHex(16), new Date().toISOString()).run();
    af = await afiliadoPorCodigo(env, code);
  }
  if (!af || af.tenant_id === tenantId) return null; // auto-referido NO
  await env.DB.prepare(
    "INSERT INTO referidos (tenant_id, codigo, fecha) VALUES (?1,?2,?3) ON CONFLICT(tenant_id) DO NOTHING"
  ).bind(tenantId, af.codigo, new Date().toISOString()).run();
  return af;
}
/* Marca un mes pagado como comisionable (30%, tope 12 meses por tenant). Idempotente por
   mp_payment_id. Llamado desde el webhook de MP con el authorized_payment aprobado. */
async function otorgarComision(env, tenant, pago, mpPaymentId){
  try {
    await ensureAfiliadosSchema(env);
    let ref = await env.DB.prepare("SELECT codigo FROM referidos WHERE tenant_id = ?1").bind(tenant.id).first();
    if (!ref && tenant.ref_code){
      // self-heal: tenants referidos antes de esta version solo tienen tenants.ref_code
      const afOld = await registrarReferido(env, tenant.id, tenant.ref_code);
      if (afOld) ref = { codigo: afOld.codigo };
    }
    if (!ref) return null;
    const af = await afiliadoPorCodigo(env, ref.codigo);
    if (!af) return null;
    const pagoId = String(mpPaymentId || "");
    const ya = await env.DB.prepare("SELECT id FROM comisiones WHERE tipo = 'comision' AND mp_payment_id = ?1").bind(pagoId).first();
    if (ya) return null; // MP re-notifica: no duplicar
    const meses = await env.DB.prepare(
      "SELECT COUNT(*) AS n FROM comisiones c WHERE c.tenant_id = ?1 AND c.tipo = 'comision' AND NOT EXISTS (SELECT 1 FROM comisiones r WHERE r.tipo = 'reversa' AND r.mp_payment_id = c.mp_payment_id)"
    ).bind(tenant.id).first();
    if (((meses && Number(meses.n)) || 0) >= AFILIADO_TOPE_MESES) return null; // tope 12 meses
    /* 21-ago-2026: el fallback era PLANES[tenant.plan], y con el modelo de packs el plan es
       'base' (no está en PLANES) -> daba 0 y el afiliado se quedaba sin su comisión en
       silencio. Ahora, si MP no mandó el monto en el webhook, se usa lo que ese tenant paga
       de packs, que es exactamente su mensualidad. */
    let base = Number((pago && (pago.transaction_amount || (pago.payment && pago.payment.transaction_amount))) || 0);
    if (!(base > 0)) base = await montoMensualTenant(env, tenant);
    if (!(base > 0)) return null;
    const comision = Math.round(base * AFILIADO_COMISION * 100) / 100;
    const pagoRealId = String((pago && pago.payment && pago.payment.id) || "");
    await env.DB.prepare(
      "INSERT INTO comisiones (id, codigo, tenant_id, tipo, mes, mp_payment_id, mp_pago_id, monto_base, monto, fecha) VALUES (?1,?2,?3,'comision',?4,?5,?6,?7,?8,?9)"
    ).bind(crypto.randomUUID(), af.codigo, tenant.id, mesActualUTC(), pagoId, pagoRealId, base, comision, new Date().toISOString()).run();
    try {
      await alertaCorreoAndres(env,
        "AFILIADOS: comision de S/" + comision + " para " + af.codigo,
        "Referido: " + (tenant.academia || tenant.id) + " pago S/" + base + " en packs.\n" +
        "Afiliado: " + af.nombre + " (" + af.codigo + ") gana S/" + comision + " (30%).\n" +
        "Saldo del afiliado: S/" + (await saldoAfiliado(env, af.codigo)) + " · payout " + (af.tenant_id ? "automatico (credito en su cobro de MP)" : "PayPal (flag " + (env.PAYPAL_PAYOUTS_ON === "1" ? "ON" : "OFF") + ")") + ".");
    } catch (e) {}
    return comision;
  } catch (e) { console.error("otorgarComision", e); return null; }
}
/* Reversa por refund/contracargo: anula la comision de ESE pago (idempotente). */
async function revertirComision(env, mpId){
  try {
    await ensureAfiliadosSchema(env);
    const id = String(mpId || "");
    if (!id) return null;
    const c = await env.DB.prepare(
      "SELECT * FROM comisiones WHERE tipo = 'comision' AND (mp_payment_id = ?1 OR mp_pago_id = ?1)"
    ).bind(id).first();
    if (!c) return null;
    const ya = await env.DB.prepare("SELECT id FROM comisiones WHERE tipo = 'reversa' AND mp_payment_id = ?1").bind(c.mp_payment_id).first();
    if (ya) return null;
    await env.DB.prepare(
      "INSERT INTO comisiones (id, codigo, tenant_id, tipo, mes, mp_payment_id, mp_pago_id, monto_base, monto, fecha) VALUES (?1,?2,?3,'reversa',?4,?5,?6,?7,?8,?9)"
    ).bind(crypto.randomUUID(), c.codigo, c.tenant_id, mesActualUTC(), c.mp_payment_id, c.mp_pago_id, c.monto_base, -Number(c.monto), new Date().toISOString()).run();
    try { await alertaCorreoAndres(env, "AFILIADOS: reversa de S/" + c.monto + " (" + c.codigo + ")", "Refund/contracargo del pago MP " + id + ": la comision de ese mes se revierte (regla 5 del programa)."); } catch (e) {}
    return c;
  } catch (e) { console.error("revertirComision", e); return null; }
}
/* Payout automatico v1 (cron diario): afiliados-tenant con saldo >= S/50 -> el saldo se baja
   del monto de SU preapproval; el webhook del cobro descontado liquida y restaura el precio. */
async function aplicarCreditosAfiliados(env){
  await ensureAfiliadosSchema(env);
  if (!env.MP_ACCESS_TOKEN) return;
  let afs = [];
  try { const r = await env.DB.prepare("SELECT * FROM afiliados WHERE tenant_id != ''").all(); afs = r.results || []; } catch (e) { return; }
  for (const af of afs){
    try {
      if (Number(af.descuento_pen) > 0) continue; // ya hay un descuento en vuelo
      const saldo = await saldoAfiliado(env, af.codigo);
      if (saldo < AFILIADO_PAYOUT_MIN) continue;
      const t = await env.DB.prepare("SELECT * FROM tenants WHERE id = ?1").bind(af.tenant_id).first();
      if (!t || t.estado !== "activo" || t.mp_sub_status !== "authorized" || !t.mp_preapproval_id) continue;
      const precio = await montoMensualTenant(env, t);
      if (!(precio > 0)) continue; // no paga nada este mes: no hay cobro que descontar (queda en saldo)
      const aplicable = Math.min(saldo, precio - 1); // MP no acepta monto 0: siempre queda >= S/1
      if (!(aplicable > 0)) continue;
      const up = await mpFetch(env, "/preapproval/" + encodeURIComponent(t.mp_preapproval_id), {
        method: "PUT",
        body: { auto_recurring: { transaction_amount: Math.round((precio - aplicable) * 100) / 100, currency_id: "PEN" } }
      });
      if (!up.ok){ console.error("aplicarCreditosAfiliados PUT", af.codigo, up.status); continue; }
      await env.DB.prepare("UPDATE afiliados SET descuento_pen = ?1 WHERE codigo = ?2").bind(aplicable, af.codigo).run();
      try {
        await alertaCorreoAndres(env,
          "AFILIADOS: credito de S/" + aplicable + " aplicado a " + (t.academia || af.codigo),
          "El afiliado " + af.nombre + " (" + af.codigo + ") tenia S/" + saldo + " de saldo.\nSu siguiente cobro de MP baja de S/" + precio + " a S/" + (Math.round((precio - aplicable) * 100) / 100) + ". Al confirmarse el pago, el precio se restaura solo.");
      } catch (e) {}
    } catch (e) { console.error("aplicarCreditosAfiliados", af && af.codigo, e); }
  }
}
/* Al confirmarse el cobro DESCONTADO del afiliado-tenant: liquidar el saldo usado y restaurar
   el precio del plan en su preapproval. Llamado desde el webhook (pago aprobado). */
async function liquidarCreditoAfiliado(env, tenant){
  try {
    await ensureAfiliadosSchema(env);
    const af = await env.DB.prepare("SELECT * FROM afiliados WHERE tenant_id = ?1 AND descuento_pen > 0").bind(tenant.id).first();
    if (!af) return;
    const usado = Math.round(Number(af.descuento_pen) * 100) / 100;
    await env.DB.prepare(
      "INSERT INTO comisiones (id, codigo, tenant_id, tipo, mes, monto, fecha) VALUES (?1,?2,?3,'payout_credito',?4,?5,?6)"
    ).bind(crypto.randomUUID(), af.codigo, tenant.id, mesActualUTC(), -usado, new Date().toISOString()).run();
    await env.DB.prepare("UPDATE afiliados SET descuento_pen = 0 WHERE codigo = ?1").bind(af.codigo).run();
    const precio = await montoMensualTenant(env, tenant);
    if (precio > 0 && tenant.mp_preapproval_id && env.MP_ACCESS_TOKEN){
      const up = await mpFetch(env, "/preapproval/" + encodeURIComponent(tenant.mp_preapproval_id), {
        method: "PUT", body: { auto_recurring: { transaction_amount: precio, currency_id: "PEN" } }
      });
      if (!up.ok){
        try { await alertaCorreoAndres(env, "AFILIADOS: RESTAURAR PRECIO A MANO de " + (tenant.academia || tenant.id), "Se liquido el credito de S/" + usado + " de " + af.codigo + " pero MP no dejo restaurar el precio del preapproval " + tenant.mp_preapproval_id + " a S/" + precio + " (status " + up.status + "). Revisar en MP."); } catch (e) {}
        return;
      }
    }
    try { await alertaCorreoAndres(env, "AFILIADOS: payout de S/" + usado + " liquidado (" + af.codigo + ")", "El cobro descontado de " + (tenant.academia || tenant.id) + " se confirmo. Saldo restante del afiliado: S/" + (await saldoAfiliado(env, af.codigo)) + ". Precio del plan restaurado."); } catch (e) {}
  } catch (e) { console.error("liquidarCreditoAfiliado", e); }
}
/* Riel PayPal Payouts (afiliados cash): DETRAS DE FLAG hasta que Andres confirme la
   aprobacion del API. Con el flag apagado solo avisa cuanto se debe (sin mover dinero). */
async function payoutsPayPalAfiliados(env){
  await ensureAfiliadosSchema(env);
  let afs = [];
  try { const r = await env.DB.prepare("SELECT * FROM afiliados WHERE tenant_id = ''").all(); afs = r.results || []; } catch (e) { return; }
  const pendientes = [];
  for (const af of afs){
    const saldo = await saldoAfiliado(env, af.codigo);
    if (saldo >= AFILIADO_PAYOUT_MIN) pendientes.push({ af, saldo });
  }
  if (!pendientes.length) return;
  const flagOn = env.PAYPAL_PAYOUTS_ON === "1" && env.PAYPAL_CLIENT_ID && env.PAYPAL_CLIENT_SECRET;
  if (!flagOn){
    try {
      await alertaCorreoAndres(env,
        "AFILIADOS: " + pendientes.length + " payout(s) PayPal en espera (flag OFF)",
        pendientes.map(p => "· " + p.af.nombre + " (" + p.af.codigo + "): S/" + p.saldo + (p.af.email_paypal ? " -> " + p.af.email_paypal : " (SIN correo PayPal)")).join("\n") +
        "\n\nEl riel PayPal esta detras del flag PAYPAL_PAYOUTS_ON hasta confirmar la aprobacion del Payouts API. Para encenderlo: secrets PAYPAL_CLIENT_ID, PAYPAL_CLIENT_SECRET, PAYPAL_TC_USD (tipo de cambio PEN->USD) y PAYPAL_PAYOUTS_ON=1.");
    } catch (e) {}
    return;
  }
  const tc = Number(env.PAYPAL_TC_USD) || 0; // ej. 3.75 (S/ por US$); sin tipo de cambio NO se paga
  if (!(tc > 0)){
    try { await alertaCorreoAndres(env, "AFILIADOS: falta PAYPAL_TC_USD para pagar", "El flag PayPal esta ON pero no hay tipo de cambio PEN->USD configurado (secret PAYPAL_TC_USD). No se envio ningun pago."); } catch (e) {}
    return;
  }
  try {
    const basic = btoa(env.PAYPAL_CLIENT_ID + ":" + env.PAYPAL_CLIENT_SECRET);
    const tokRes = await fetch("https://api-m.paypal.com/v1/oauth2/token", {
      method: "POST",
      headers: { "content-type": "application/x-www-form-urlencoded", authorization: "Basic " + basic },
      body: "grant_type=client_credentials"
    });
    const tok = await tokRes.json().catch(() => ({}));
    if (!tokRes.ok || !tok.access_token) throw new Error("PayPal oauth " + tokRes.status);
    const items = pendientes.filter(p => p.af.email_paypal).map((p, i) => ({
      recipient_type: "EMAIL",
      amount: { value: (Math.round((p.saldo / tc) * 100) / 100).toFixed(2), currency: "USD" },
      receiver: p.af.email_paypal,
      note: "Comision del programa de afiliados de Batuta (batuta.lat)",
      sender_item_id: "af-" + p.af.codigo + "-" + mesActualUTC()
    }));
    if (!items.length) return;
    const res = await fetch("https://api-m.paypal.com/v1/payments/payouts", {
      method: "POST",
      headers: { "content-type": "application/json", authorization: "Bearer " + tok.access_token },
      body: JSON.stringify({
        sender_batch_header: { sender_batch_id: "batuta-af-" + mesActualUTC(), email_subject: "Tu comision de afiliado de Batuta" },
        items
      })
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error("PayPal payouts " + res.status + " " + JSON.stringify(data).slice(0, 300));
    for (const p of pendientes.filter(x => x.af.email_paypal)){
      await env.DB.prepare(
        "INSERT INTO comisiones (id, codigo, tipo, mes, monto, fecha) VALUES (?1,?2,'payout_paypal',?3,?4,?5)"
      ).bind(crypto.randomUUID(), p.af.codigo, mesActualUTC(), -p.saldo, new Date().toISOString()).run();
    }
    try { await alertaCorreoAndres(env, "AFILIADOS: payout PayPal enviado (" + items.length + ")", pendientes.filter(x => x.af.email_paypal).map(p => "· " + p.af.nombre + ": S/" + p.saldo + " (US$" + (Math.round((p.saldo / tc) * 100) / 100) + ") -> " + p.af.email_paypal).join("\n") + "\nBatch: " + ((data.batch_header && data.batch_header.payout_batch_id) || "?")); } catch (e) {}
  } catch (e) {
    console.error("payoutsPayPalAfiliados", e);
    try { await alertaCorreoAndres(env, "AFILIADOS: fallo el payout PayPal", String(e && e.message || e) + "\nNingun saldo se marco como pagado; se reintenta el proximo mes o a mano."); } catch (e2) {}
  }
}
/* Stats de UN afiliado (para el panel por token y su/afiliados). */
async function statsAfiliado(env, af){
  const mes = mesActualUTC();
  const refs = await env.DB.prepare(
    "SELECT r.fecha, t.academia, t.plan, t.estado, t.mp_sub_status FROM referidos r JOIN tenants t ON t.id = r.tenant_id WHERE r.codigo = ?1 ORDER BY r.fecha DESC"
  ).bind(af.codigo).all().catch(() => ({ results: [] }));
  const lista = refs.results || [];
  const activos = lista.filter(r => r.estado === "activo" && (r.mp_sub_status === "authorized" || r.mp_sub_status === "anual")).length;
  const trials = lista.filter(r => r.estado === "trial").length;
  const cMes = await env.DB.prepare(
    "SELECT COALESCE(SUM(monto),0) AS s FROM comisiones WHERE codigo = ?1 AND mes = ?2 AND tipo IN ('comision','reversa')"
  ).bind(af.codigo, mes).first().catch(() => null);
  const cTotal = await env.DB.prepare(
    "SELECT COALESCE(SUM(monto),0) AS s FROM comisiones WHERE codigo = ?1 AND tipo IN ('comision','reversa')"
  ).bind(af.codigo).first().catch(() => null);
  return {
    codigo: af.codigo, nombre: af.nombre,
    link: "https://batuta.lat/?ref=" + af.codigo,
    clics: Number(af.clics) || 0,
    referidos: lista.length, trials, activos,
    comision_mes_pen: Math.round(((cMes && Number(cMes.s)) || 0) * 100) / 100,
    comision_acumulada_pen: Math.round(((cTotal && Number(cTotal.s)) || 0) * 100) / 100,
    saldo_pendiente_pen: await saldoAfiliado(env, af.codigo),
    payout: af.tenant_id ? "credito automatico en su cobro de MP" : "PayPal mensual (saldo minimo S/" + AFILIADO_PAYOUT_MIN + ")"
  };
}

/* ---------- Activacion (15-jul-2026): LA metrica #1 del negocio ----------
   Tenant activado = cargo >=5 alumnos Y registro >=1 cobro (compras no 'iniciada') en
   cualquier momento. El plan maestro exige medirla en los primeros 7 dias; aqui se calcula
   el estado actual y su/funnel lo cruza con la fecha de creacion. */
async function tenantActivado(env, tenantId){
  try {
    const a = await env.DB.prepare("SELECT COUNT(*) AS n FROM alumnos WHERE tenant_id = ?1").bind(tenantId).first();
    if ((Number(a && a.n) || 0) < 5) return { activado: false, alumnos: Number(a && a.n) || 0, cobros: 0 };
    const c = await env.DB.prepare("SELECT COUNT(*) AS n FROM compras WHERE tenant_id = ?1 AND estado != 'iniciada'").bind(tenantId).first();
    const cobros = Number(c && c.n) || 0;
    return { activado: cobros >= 1, alumnos: Number(a.n) || 0, cobros };
  } catch (e) { return { activado: false, alumnos: 0, cobros: 0 }; }
}

/* Bolsa del equipo segun edad del tenant: 60/mes los primeros 90 dias, 30/mes despues.
   Al agotarse se pueden comprar packs extra (ver PACKS_MENSAJES / consumirMensajeExtra). */
function limiteSoporteAdmin(tenant){
  if ((tenant && tenant.plan) === "gratis") return 10; // plan Gratis: 10 mensajes/mes (los packs siguen comprables)
  try {
    const dias = (Date.now() - new Date(tenant.creado).getTime()) / 86400000;
    if (Number.isFinite(dias) && dias > 90) return ONBOARDING_LIMITE_ADMIN_90D;
  } catch (e) {}
  return ONBOARDING_LIMITE_ADMIN;
}
function claveSoporteIA(who){
  if (who.admin){
    const pid = (who.profesor && who.profesor.id) ? who.profesor.id : who.tenant.id;
    return "admin:" + pid + ":" + mesActualUTC();
  }
  return "alumno:" + who.cu.id + ":" + mesActualUTC();
}
/* Cuenta atomico (upsert con tope en el WHERE): dos requests concurrentes ya no pueden
   colarse por la ventana entre SELECT e INSERT. meta.changes = 0 -> tope alcanzado. */
async function onboardingContar(env, clave, limite){
  const res = await env.DB.prepare(
    "INSERT INTO onboarding_ia_uso (clave, mensajes) VALUES (?1, 1) ON CONFLICT(clave) DO UPDATE SET mensajes = mensajes + 1 WHERE mensajes < ?2"
  ).bind(clave, limite).run();
  if (!res.meta || !res.meta.changes) return { usados: limite, restantes: 0, tope: true };
  const row = await env.DB.prepare("SELECT mensajes FROM onboarding_ia_uso WHERE clave = ?1").bind(clave).first();
  const usados = row ? Number(row.mensajes) : 1;
  return { usados, restantes: Math.max(0, limite - usados), tope: false };
}
/* Log de conversaciones del soporte IA: cada pregunta real alimenta las guias y el roadmap.
   Lazy CREATE (patron ensureErpSchema): la tabla nace al primer uso, sin migracion manual. */
let SOPORTE_LOG_OK = false;
async function ensureSoporteLogSchema(env){
  if (SOPORTE_LOG_OK) return;
  try {
    await env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS soporte_ia_log (id INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id TEXT NOT NULL, quien TEXT DEFAULT '', pregunta TEXT DEFAULT '', respuesta TEXT DEFAULT '', historial TEXT DEFAULT '', fecha TEXT DEFAULT '')"
    ).run();
    /* tabla nacida antes de la columna historial: ALTER idempotente (falla mudo si ya existe) */
    try { await env.DB.prepare("ALTER TABLE soporte_ia_log ADD COLUMN historial TEXT DEFAULT ''").run(); } catch (e) {}
    SOPORTE_LOG_OK = true;
  } catch (e) { /* sin log no se cae el soporte */ }
}
/* El historial va al log porque lo manda el CLIENTE (puede venir forjado): sin el,
   una respuesta dirigida por historial falso pareceria alucinacion del bot al triarla. */
async function logSoporteIA(env, tenantId, quien, pregunta, respuesta, historial){
  try {
    await ensureSoporteLogSchema(env);
    let hist = "";
    try { hist = historial && historial.length ? JSON.stringify(historial).slice(0, 2000) : ""; } catch (e) {}
    await env.DB.prepare(
      "INSERT INTO soporte_ia_log (tenant_id, quien, pregunta, respuesta, historial, fecha) VALUES (?1, ?2, ?3, ?4, ?5, ?6)"
    ).bind(tenantId, quien, String(pregunta || "").slice(0, 500), String(respuesta || "").slice(0, 1500), hist, new Date().toISOString()).run();
  } catch (e) { /* nunca rompe la respuesta al usuario */ }
}

/* ---------- Web Push (VAPID): sin claves -> no-op ---------- */
/* ---------- Web Push REAL (VAPID ES256 + RFC 8291 aes128gcm), solo crypto.subtle ---------- */
function b64uToBytes(s){
  s = s.replace(/-/g, "+").replace(/_/g, "/"); while (s.length % 4) s += "=";
  const bin = atob(s); const a = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  return a;
}
function bytesToB64u(bytes){
  const a = new Uint8Array(bytes); let bin = "";
  for (let i = 0; i < a.length; i++) bin += String.fromCharCode(a[i]);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
let VAPID_KEY_CACHE = null;
async function vapidPrivateKey(env){
  if (VAPID_KEY_CACHE) return VAPID_KEY_CACHE;
  const jwk = JSON.parse(env.VAPID_PRIVATE_KEY); // JWK {kty:EC, crv:P-256, d, x, y}
  VAPID_KEY_CACHE = await crypto.subtle.importKey("jwk", jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
  return VAPID_KEY_CACHE;
}
async function vapidJwt(env, audience){
  const header = bytesToB64u(enc.encode(JSON.stringify({ typ: "JWT", alg: "ES256" })));
  const payload = bytesToB64u(enc.encode(JSON.stringify({
    aud: audience, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: MARCA.vapidSubject
  })));
  const si = header + "." + payload;
  const key = await vapidPrivateKey(env);
  const sig = await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, enc.encode(si));
  return si + "." + bytesToB64u(sig); // firma raw r||s: exactamente lo que pide JWS ES256
}
async function hkdfBits(salt, ikm, info, len){
  const key = await crypto.subtle.importKey("raw", ikm, "HKDF", false, ["deriveBits"]);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: "HKDF", hash: "SHA-256", salt, info }, key, len * 8));
}
/* Cifra y envía el payload a UNA suscripción (RFC 8291). Devuelve el status HTTP. */
async function pushAUno(env, sub, payloadStr){
  const uaPub = b64uToBytes(sub.p256dh);   // punto P-256 sin comprimir (65 bytes)
  const auth = b64uToBytes(sub.auth);      // secreto auth (16 bytes)
  const asKeys = await crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"]);
  const asPub = new Uint8Array(await crypto.subtle.exportKey("raw", asKeys.publicKey));
  const uaKey = await crypto.subtle.importKey("raw", uaPub, { name: "ECDH", namedCurve: "P-256" }, false, []);
  const ecdh = new Uint8Array(await crypto.subtle.deriveBits({ name: "ECDH", public: uaKey }, asKeys.privateKey, 256));
  const infoIkm = new Uint8Array(14 + uaPub.length + asPub.length);
  infoIkm.set(enc.encode("WebPush: info\0"), 0); infoIkm.set(uaPub, 14); infoIkm.set(asPub, 14 + uaPub.length);
  const ikm = await hkdfBits(auth, ecdh, infoIkm, 32);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const cek = await hkdfBits(salt, ikm, enc.encode("Content-Encoding: aes128gcm\0"), 16);
  const nonce = await hkdfBits(salt, ikm, enc.encode("Content-Encoding: nonce\0"), 12);
  const plainBytes = enc.encode(payloadStr);
  const plain = new Uint8Array(plainBytes.length + 1);
  plain.set(plainBytes, 0); plain[plainBytes.length] = 2; // delimitador de último registro
  const aesKey = await crypto.subtle.importKey("raw", cek, "AES-GCM", false, ["encrypt"]);
  const cipher = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv: nonce }, aesKey, plain));
  // header aes128gcm: salt(16) | rs(4) | idlen(1) | keyid(65) | ciphertext
  const body = new Uint8Array(21 + asPub.length + cipher.length);
  body.set(salt, 0);
  new DataView(body.buffer).setUint32(16, 4096);
  body[20] = asPub.length;
  body.set(asPub, 21);
  body.set(cipher, 21 + asPub.length);
  const jwt = await vapidJwt(env, new URL(sub.endpoint).origin);
  const r = await fetch(sub.endpoint, {
    method: "POST",
    headers: {
      "TTL": "86400", "Urgency": "normal",
      "Content-Encoding": "aes128gcm", "Content-Type": "application/octet-stream",
      "Authorization": "vapid t=" + jwt + ", k=" + env.VAPID_PUBLIC_KEY
    },
    body
  });
  return r.status;
}
async function enviarPushA(env, subs, payload){
  if (!env.VAPID_PUBLIC_KEY || !env.VAPID_PRIVATE_KEY || !subs || !subs.length) return 0;
  const payloadStr = JSON.stringify(payload || {});
  let ok = 0;
  for (const s of subs){
    try {
      const st = await pushAUno(env, s, payloadStr);
      if (st === 404 || st === 410){
        // suscripción muerta: se limpia sola
        try { await env.DB.prepare("DELETE FROM push_subs WHERE endpoint = ?1").bind(s.endpoint).run(); } catch (e) {}
      } else if (st >= 200 && st < 300) ok++;
    } catch (e) { /* seguir con las demás suscripciones */ }
  }
  return ok;
}
async function avisarPush(env, tenantId, info){
  const { results } = await env.DB.prepare("SELECT * FROM push_subs WHERE tenant_id = ?1 AND cuenta_id IS NULL").bind(tenantId).all();
  return enviarPushA(env, results || [], info);
}
async function avisarPushAlumno(env, tenantId, cuentaId, payload){
  if (!cuentaId) return 0;
  const { results } = await env.DB.prepare("SELECT * FROM push_subs WHERE tenant_id = ?1 AND cuenta_id = ?2").bind(tenantId, cuentaId).all();
  return enviarPushA(env, results || [], payload);
}

/* Tipografia de Batuta (01-ago-2026). Se fueron Bricolage Grotesque y Space Grotesk:
   las dos estan en la lista negra de "look AI" de Andres. Cabinet Grotesk + Switzer,
   self-hosted desde Fontshare (ITF Free Font License). Los .woff2 salen por /app/fonts/,
   que es la unica ruta que atraviesa el rewrite de batuta.lat hacia este worker. */
const FUENTES_BATUTA_CSS =
  "@font-face{font-family:'Cabinet Grotesk';src:url('/app/fonts/CabinetGrotesk-700.woff2') format('woff2');font-weight:700;font-style:normal;font-display:swap}" +
  "@font-face{font-family:'Switzer';src:url('/app/fonts/Switzer-400.woff2') format('woff2');font-weight:400;font-style:normal;font-display:swap}" +
  "@font-face{font-family:'Switzer';src:url('/app/fonts/Switzer-500.woff2') format('woff2');font-weight:500;font-style:normal;font-display:swap}" +
  "@font-face{font-family:'Switzer';src:url('/app/fonts/Switzer-600.woff2') format('woff2');font-weight:600;font-style:normal;font-display:swap}";

/* ---------- PWA: service workers servidos por el worker ----------
   El panel vive en /app/panel y el portal en /app/a/<slug> (rutas del worker),
   así que los SW también se sirven desde /app/... para que su scope los cubra:
   sw-panel scope /app/panel · sw-alumno scope /app/a/ (sin chocar entre sí). */
function swFuente(fallbackUrl){
  return "self.addEventListener('install',function(e){self.skipWaiting();});\n" +
    "self.addEventListener('activate',function(e){e.waitUntil(self.clients.claim());});\n" +
    "self.addEventListener('push',function(e){\n" +
    "  var d={};try{d=e.data?e.data.json():{};}catch(err){try{d={body:e.data.text()};}catch(e2){}}\n" +
    "  var title=d.title||'Batuta';\n" +
    "  var body=d.body||(d.paquete?(d.paquete+(d.monto?' · S/ '+d.monto:'')):'');\n" +
    "  var url=d.url||'" + fallbackUrl + "';\n" +
    "  e.waitUntil(self.registration.showNotification(title,{body:body,icon:'/icons/batuta-192.png',badge:'/icons/batuta-192.png',data:{url:url}}));\n" +
    "});\n" +
    "self.addEventListener('notificationclick',function(e){\n" +
    "  e.notification.close();\n" +
    "  var url=(e.notification.data&&e.notification.data.url)||'" + fallbackUrl + "';\n" +
    "  e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(function(ws){\n" +
    "    for(var i=0;i<ws.length;i++){ if(ws[i].url.indexOf(url)!==-1 && 'focus' in ws[i]) return ws[i].focus(); }\n" +
    "    if(clients.openWindow) return clients.openWindow(url);\n" +
    "  }));\n" +
    "});\n" +
    "self.addEventListener('fetch',function(){});\n";
}
const ICONOS_PWA = [
  { src: "/icons/batuta-192.png", sizes: "192x192", type: "image/png" },
  { src: "/icons/batuta-512.png", sizes: "512x512", type: "image/png" },
  { src: "/icons/batuta-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
];

/* ---------- Libro de Reclamaciones virtual (LRV): obligatorio para comercio electronico
   (enlace visible, libro funcional 24/7, acuse automatico, respuesta en max 15 dias habiles). ---------- */
async function ensureLibroSchema(env){
  await env.DB.prepare(
    "CREATE TABLE IF NOT EXISTS reclamos (id TEXT PRIMARY KEY, tipo TEXT NOT NULL, nombre TEXT DEFAULT '', documento TEXT DEFAULT '', domicilio TEXT DEFAULT '', email TEXT DEFAULT '', telefono TEXT DEFAULT '', menor INTEGER DEFAULT 0, apoderado TEXT DEFAULT '', servicio TEXT DEFAULT '', monto REAL DEFAULT 0, detalle TEXT DEFAULT '', pedido TEXT DEFAULT '', respuesta TEXT DEFAULT '', respondido TEXT DEFAULT '', estado TEXT DEFAULT 'pendiente', creado TEXT DEFAULT '')"
  ).run();
}
/* Dias habiles (L-V) transcurridos desde una fecha ISO. Aproximacion sin feriados:
   sesga a favor del consumidor (alerta ANTES), que es el lado correcto del error. */
function diasHabilesDesde(isoCreado){
  const d = new Date(isoCreado); const hoy = new Date(); let n = 0;
  while (d < hoy){ d.setUTCDate(d.getUTCDate() + 1); const dow = d.getUTCDay(); if (dow !== 0 && dow !== 6) n++; }
  return n;
}
async function nuevoCodigoReclamo(env){
  const anio = new Date().getFullYear();
  const row = await env.DB.prepare("SELECT COUNT(*) AS n FROM reclamos WHERE id LIKE ?1").bind("LRV-" + anio + "-%").first();
  return "LRV-" + anio + "-" + String(((row && Number(row.n)) || 0) + 1).padStart(4, "0");
}
